            preview_body = tk.Label(preview, text="", bg="#f1efff", fg="#334155", font=("Segoe UI",16), justify="left", anchor="nw", wraplength=760)
            preview_body.pack(fill="both", expand=True, padx=32, pady=20)
            edit_panel = tk.Frame(workspace, bg="#f8fafc", width=350)
