    def _update_target_path(self):
        """Return the running source file, when NevOS is running as a .py script."""
        target = Path(__file__).resolve()
        if target.suffix.lower() != ".py" or not target.is_file():
            raise RuntimeError("NevOS could not locate its Python source file. Run the .py version to install manual updates.")
        return target

    def open_backup_folder(self):
        folder = Path.home() / "NevOS_Backups"
        folder.mkdir(parents=True, exist_ok=True)
        try:
            if os.name == "nt":
                os.startfile(str(folder))
            else:
                webbrowser.open(folder.as_uri())
        except Exception as exc:
            messagebox.showinfo("NevOS Backups", f"Backup folder:\n{folder}\n\n{exc}")

    def install_manual_update(self):
        path = filedialog.askopenfilename(
            parent=self.root, title="Choose a trusted NevOS update",
            filetypes=[("NevOS update files", "*.py *.zip"), ("Python source", "*.py"), ("ZIP package", "*.zip")])
        if not path:
            return
        update_path = Path(path)
        try:
            if update_path.stat().st_size > MAX_UPDATE_BYTES:
                raise ValueError("The selected update is larger than 10 MB.")
            if update_path.suffix.lower() == ".py":
                source = update_path.read_bytes()
            elif update_path.suffix.lower() == ".zip":
                with zipfile.ZipFile(update_path, "r") as archive:
                    candidates = [i for i in archive.infolist()
                                  if not i.is_dir() and Path(i.filename).suffix.lower() == ".py"
                                  and "nevos" in Path(i.filename).name.lower()]
                    if len(candidates) != 1:
                        raise ValueError("The ZIP must contain exactly one Python file with 'NevOS' in its filename.")
                    item = candidates[0]
                    if item.file_size > MAX_UPDATE_BYTES:
                        raise ValueError("The Python file inside the ZIP is larger than 10 MB.")
                    source = archive.read(item)
            else:
                raise ValueError("Choose a .py file or .zip package.")
            if not source or len(source) > MAX_UPDATE_BYTES:
                raise ValueError("The update file is empty or larger than 10 MB.")
            decoded = source.decode("utf-8-sig")
            ast.parse(decoded, filename=update_path.name, mode="exec")
            target = self._update_target_path()
        except (OSError, UnicodeError, SyntaxError, zipfile.BadZipFile, ValueError, RuntimeError) as exc:
            messagebox.showerror("Update validation failed", f"NevOS did not install this update.\n\n{exc}", parent=self.root)
            return
        except Exception as exc:
            messagebox.showerror("Update validation failed", f"Could not read the selected update.\n\n{exc}", parent=self.root)
            return

        answer = messagebox.askyesno(
            "Confirm manual update",
            f"Install this update?\n\nFile: {update_path.name}\nTarget: {target}\nSize: {len(source):,} bytes\n\n"
            "Only continue if you trust the source. A syntax check does not make unknown code safe.\n\n"
            "NevOS will save a backup before replacing the current file.", parent=self.root)
        if not answer:
            return
        backup_dir = Path.home() / "NevOS_Backups"
        backup_dir.mkdir(parents=True, exist_ok=True)
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        backup = backup_dir / f"{target.stem}_{stamp}{target.suffix}.bak"
        temp_path = None
        try:
            shutil.copy2(target, backup)
            # Write beside the target so replacement remains on the same volume.
            fd, temp_name = tempfile.mkstemp(prefix=".nevos_update_", suffix=".py", dir=str(target.parent))
            temp_path = Path(temp_name)
            with os.fdopen(fd, "wb") as out:
                out.write(source)
                out.flush()
                os.fsync(out.fileno())
            # Re-parse the exact bytes that will be installed.
            ast.parse(temp_path.read_text(encoding="utf-8-sig"), filename=str(temp_path), mode="exec")
            os.replace(str(temp_path), str(target))
            temp_path = None
        except Exception as exc:
            if temp_path and temp_path.exists():
                try: temp_path.unlink()
                except OSError: pass
            messagebox.showerror("Update failed", f"NevOS could not install the update.\n\nBackup (if created): {backup}\n\nError: {exc}", parent=self.root)
            return
        restart = messagebox.askyesno(
            "Update installed",
            f"The update file was installed successfully.\n\nBackup saved to:\n{backup}\n\n"
            "Restart NevOS now to run the updated version? Save your work in other apps first.", parent=self.root)
        if restart:
            try:
                self.root.destroy()
                os.execv(sys.executable, [sys.executable, str(target)])
            except Exception as exc:
                messagebox.showwarning("Restart manually", f"Close NevOS and start it again with:\npy \"{target}\"\n\n{exc}")

    def set_wallpaper(self,color):
        self.wallpaper=color
        self.wallpaper_image=None
        self.make_desktop()

    def custom_color(self):
        chosen=colorchooser.askcolor(title="Choose desktop color")[1]
        if chosen:self.set_wallpaper(chosen)

    def choose_image(self):
        path=filedialog.askopenfilename(title="Choose wallpaper",
            filetypes=[("Supported images","*.png *.gif"),("PNG images","*.png"),("GIF images","*.gif")])
        if not path:return
        try:
            self.wallpaper_image=tk.PhotoImage(file=path)
            for w in self.desktop.winfo_children():w.destroy()
            label=tk.Label(self.desktop,image=self.wallpaper_image)
            label.place(x=0,y=0,relwidth=1,relheight=1); label.lower()
            tk.Label(self.desktop,text="NevOS",font=("Segoe UI",34,"bold"),
                     bg=self.wallpaper,fg="white").place(x=24,y=18)
            for i,(name,cmd) in enumerate([("Files",self.files),("Slides",self.slides),
                                           ("Sheets",self.sheets),("Store",self.store),
                                           ("Settings",self.settings)]):
                tk.Button(self.desktop,text=name,command=cmd,bg=self.accent,fg="white").place(x=30,y=100+i*48)
        except Exception:
            messagebox.showerror("NevOS","Could not load that image. Try a PNG or GIF file.")


    def paint_pro(self):
        """Layer-based Paint Pro using Pillow and Tkinter; edits remain local."""
        from PIL import Image, ImageDraw, ImageFilter, ImageEnhance, ImageTk
        W,H=900,560
        win=self.window("NevOS Paint Studio X", "1120x760"); win.configure(bg="#111827")
        bar=tk.Frame(win,bg="#172554",padx=8,pady=7); bar.pack(fill="x")
        status=tk.StringVar(value="Paint Studio X • layered editing • saved locally")
        layers=[{"name":"Layer 1","image":Image.new("RGBA",(W,H),(0,0,0,0)),"visible":True}]
        active=[0]; color=["#21d4fd"]; tool=tk.StringVar(value="Brush"); size=tk.IntVar(value=5)
        history=[]; redo_stack=[]; start=[None]; preview=[None]; photo=[None]; selection=[None]
        body=tk.Frame(win,bg="#111827"); body.pack(fill="both",expand=True)
        canvas=tk.Canvas(body,width=W,height=H,bg="#f8fafc",highlightthickness=0,cursor="crosshair")
        canvas.pack(side="left",fill="both",expand=True,padx=8,pady=8)
        side=tk.Frame(body,bg="#1e293b",width=190); side.pack(side="right",fill="y",padx=(0,8),pady=8); side.pack_propagate(False)
        def merged():
            out=Image.new("RGBA",(W,H),(255,255,255,255))
            for layer in layers:
                if layer["visible"]: out=Image.alpha_composite(out,layer["image"])
            return out.convert("RGB")
        def render():
            photo[0]=ImageTk.PhotoImage(merged()); canvas.delete("preview-image"); canvas.create_image(0,0,image=photo[0],anchor="nw",tags="preview-image"); canvas.tag_lower("preview-image")
            if selection[0]: canvas.delete("selection"); x1,y1,x2,y2=selection[0]; canvas.create_rectangle(x1,y1,x2,y2,outline="#f43f5e",dash=(4,3),tags="selection")
            refresh_layers()
        def snapshot():
            history.append([{"name":x["name"],"image":x["image"].copy(),"visible":x["visible"]} for x in layers]); del history[:-20]; redo_stack.clear()
        def refresh_layers():
            for child in layer_list.winfo_children(): child.destroy()
            for i,layer in enumerate(layers):
                b=tk.Button(layer_list,text=("● " if layer["visible"] else "○ ")+layer["name"],anchor="w",command=lambda n=i:select_layer(n),bg="#334155" if i==active[0] else "#1e293b",fg="white",relief="flat")
                b.pack(fill="x",pady=2)
        def select_layer(i): active[0]=i; refresh_layers(); status.set("Active: "+layers[i]["name"])
        def add_layer():
            snapshot(); layers.append({"name":f"Layer {len(layers)+1}","image":Image.new("RGBA",(W,H),(0,0,0,0)),"visible":True}); active[0]=len(layers)-1; render()
        def toggle_layer(): layers[active[0]]["visible"]=not layers[active[0]]["visible"]; render()
        def remove_layer():
            if len(layers)<2: messagebox.showinfo("Layers","At least one layer must remain.",parent=win); return
            if messagebox.askyesno("Delete layer",f"Delete {layers[active[0]]['name']}?",parent=win): snapshot(); layers.pop(active[0]); active[0]=max(0,active[0]-1); render()
        def choose_color():
            c=colorchooser.askcolor(color=color[0],parent=win)
            if c and c[1]: color[0]=c[1]; swatch.configure(bg=c[1])
        def coords(e): return max(0,min(W-1,e.x)),max(0,min(H-1,e.y))
        def down(e):
            snapshot(); start[0]=coords(e); selection[0]=None
            if tool.get()=="Select": selection[0]=(e.x,e.y,e.x,e.y)
            elif tool.get() in ("Brush","Eraser"):
                im=layers[active[0]]["image"]; d=ImageDraw.Draw(im); x,y=start[0]; r=max(1,size.get()//2); c=color[0] if tool.get()=="Brush" else (0,0,0,0); d.ellipse((x-r,y-r,x+r,y+r),fill=c)
            render()
        def drag(e):
            if not start[0]: return
            x,y=coords(e); x0,y0=start[0]; im=layers[active[0]]["image"]
            if tool.get() in ("Brush","Eraser"):
                d=ImageDraw.Draw(im); d.line((x0,y0,x,y),fill=color[0] if tool.get()=="Brush" else (0,0,0,0),width=max(1,size.get()))
                r=max(1,size.get()//2); c=color[0] if tool.get()=="Brush" else (0,0,0,0); d.ellipse((x-r,y-r,x+r,y+r),fill=c); start[0]=(x,y)
            elif tool.get()=="Select": selection[0]=(x0,y0,x,y)
            render()
        def up(e):
            if not start[0]: return
            x,y=coords(e); x0,y0=start[0]; im=layers[active[0]]["image"]; d=ImageDraw.Draw(im); w=max(1,size.get())
            if tool.get()=="Line": d.line((x0,y0,x,y),fill=color[0],width=w)
            elif tool.get()=="Rectangle": d.rectangle((x0,y0,x,y),outline=color[0],width=w)
            elif tool.get()=="Oval": d.ellipse((x0,y0,x,y),outline=color[0],width=w)
            elif tool.get()=="Text":
                text=simpledialog.askstring("Add text","Text to draw:",parent=win)
                if text: d.text((x0,y0),text,fill=color[0])
            start[0]=None; render()
        def undo():
            if not history:return
            redo_stack.append([{"name":x["name"],"image":x["image"].copy(),"visible":x["visible"]} for x in layers]); prev=history.pop(); layers[:]=prev; active[0]=min(active[0],len(layers)-1); render()
        def redo():
            if not redo_stack:return
            history.append([{"name":x["name"],"image":x["image"].copy(),"visible":x["visible"]} for x in layers]); prev=redo_stack.pop(); layers[:]=prev; active[0]=min(active[0],len(layers)-1); render()
        def filter_image(kind):
            snapshot(); im=layers[active[0]]["image"]
            if kind=="Blur": layers[active[0]]["image"]=im.filter(ImageFilter.GaussianBlur(2))
            elif kind=="Sharpen": layers[active[0]]["image"]=im.filter(ImageFilter.SHARPEN)
            elif kind=="Grayscale": layers[active[0]]["image"]=Image.merge("RGBA",(*[im.convert("L")]*3,im.getchannel("A")))
            elif kind=="Brighten": layers[active[0]]["image"]=ImageEnhance.Brightness(im).enhance(1.25)
            elif kind=="Rotate 90°": layers[active[0]]["image"]=im.rotate(90,expand=False)
            render(); status.set(kind+" applied to active layer")
        def crop():
            if not selection[0]: messagebox.showinfo("Crop","Choose Select tool and drag a rectangle first.",parent=win); return
            snapshot(); box=selection[0]; x1,x2=sorted((int(box[0]),int(box[2]))); y1,y2=sorted((int(box[1]),int(box[3])))
            if x2>x1 and y2>y1: layers[active[0]]["image"]=layers[active[0]]["image"].crop((x1,y1,x2,y2)).resize((W,H))
            selection[0]=None; render()
        def save():
            path=filedialog.asksaveasfilename(parent=win,defaultextension=".png",filetypes=[("PNG image","*.png"),("JPEG image","*.jpg;*.jpeg"),("WebP image","*.webp")])
            if path:
                try: merged().save(path); status.set("Saved: "+path)
                except Exception as e: messagebox.showerror("Save failed",str(e),parent=win)
        def open_image():
            path=filedialog.askopenfilename(parent=win,filetypes=[("Images","*.png *.jpg *.jpeg *.bmp *.gif *.webp")])
            if not path:return
            try:
                im=Image.open(path).convert("RGBA").resize((W,H)); snapshot(); layers.append({"name":Path(path).name,"image":im,"visible":True}); active[0]=len(layers)-1; render()
            except Exception as e: messagebox.showerror("Open image",str(e),parent=win)
        for text,cmd in [("New layer",add_layer),("Show/Hide",toggle_layer),("Delete",remove_layer),("Color",choose_color),("Undo",undo),("Redo",redo),("Crop selection",crop),("Open image",open_image),("Save PNG/JPG",save)]:
            tk.Button(bar,text=text,command=cmd,bg="#263b63",fg="white",activebackground="#0891b2",relief="flat",padx=7).pack(side="left",padx=2)
        tk.Label(bar,text="Tool",bg="#172554",fg="white").pack(side="left",padx=(8,2))
        ttk.Combobox(bar,textvariable=tool,values=["Brush","Eraser","Line","Rectangle","Oval","Text","Select"],state="readonly",width=10).pack(side="left")
        tk.Label(bar,text="Size",bg="#172554",fg="white").pack(side="left",padx=(6,2)); tk.Spinbox(bar,from_=1,to=80,textvariable=size,width=3).pack(side="left")
        swatch=tk.Label(bar,text="     ",bg=color[0]); swatch.pack(side="left",padx=4)
        tk.Label(side,text="LAYERS",font=("Segoe UI",12,"bold"),bg="#1e293b",fg="#67e8f9").pack(pady=8)
        layer_list=tk.Frame(side,bg="#1e293b"); layer_list.pack(fill="x",padx=7)
        tk.Label(side,text="FILTERS",font=("Segoe UI",12,"bold"),bg="#1e293b",fg="#67e8f9").pack(pady=(18,6))
        for label in ("Grayscale","Blur","Sharpen","Brighten","Rotate 90°"):
            tk.Button(side,text=label,command=lambda k=label:filter_image(k),bg="#334155",fg="white",relief="flat").pack(fill="x",padx=10,pady=3)
        canvas.bind("<ButtonPress-1>",down); canvas.bind("<B1-Motion>",drag); canvas.bind("<ButtonRelease-1>",up)
        win.bind("<Control-z>",lambda e:undo()); win.bind("<Control-y>",lambda e:redo())
        render(); tk.Label(win,textvariable=status,anchor="w",bg="#172554",fg="#bae6fd",padx=10,pady=5).pack(fill="x",side="bottom")

    def task_manager_pro(self):
        """Monitor NevOS windows and basic process/resource information."""
        win = self.window("Task Manager Pro", "760x520")
        win.configure(bg="#f1f5f9")
        tk.Label(win, text="Task Manager Pro", font=("Segoe UI", 22, "bold"), bg="#f1f5f9", fg="#172238").pack(anchor="w", padx=20, pady=(16, 4))
        tk.Label(win, text="Manage open NevOS windows. Resource figures are estimates for this Python simulator.", bg="#f1f5f9", fg="#526178", wraplength=700).pack(anchor="w", padx=20, pady=(0, 12))
        cols = ("window", "state")
        tree = ttk.Treeview(win, columns=cols, show="headings", height=13)
        tree.heading("window", text="Open window"); tree.heading("state", text="Status")
        tree.column("window", width=520); tree.column("state", width=130, anchor="center")
        tree.pack(fill="both", expand=True, padx=18, pady=6)
        def refresh():
            tree.delete(*tree.get_children())
            for item in self.root.winfo_children():
                if isinstance(item, tk.Toplevel) and item.winfo_exists():
                    try: tree.insert("", "end", iid=str(item.winfo_id()), values=(item.title() or "NevOS window", "Running"))
                    except tk.TclError: pass
            try:
                import tracemalloc
                if not tracemalloc.is_tracing(): tracemalloc.start()
                current, peak = tracemalloc.get_traced_memory()
                status.config(text=f"Python-tracked memory: {current/1024/1024:.1f} MB · peak {peak/1024/1024:.1f} MB · refreshes live windows")
            except Exception: status.config(text="Live window list refreshed.")
        def close_selected():
            selected = tree.selection()
            if not selected: return
            try:
                widget = win.nametowidget(tree.item(selected[0], "values")[0])
            except Exception: widget = None
            # Resolve by native Tk widget ID without touching the main desktop.
            for item in self.root.winfo_children():
                if isinstance(item, tk.Toplevel) and str(item.winfo_id()) == selected[0]:
                    if messagebox.askyesno("Close window", f"Close {item.title()}?", parent=win): item.destroy()
                    break
            refresh()
        bar=tk.Frame(win,bg="#f1f5f9"); bar.pack(fill="x",padx=18,pady=10)
        tk.Button(bar,text="Refresh",command=refresh,bg=self.accent,fg="white",relief="flat",padx=14).pack(side="left")
        tk.Button(bar,text="Close selected window",command=close_selected,bg="#dbeafe",fg="#172238",relief="flat",padx=14).pack(side="left",padx=8)
        status=tk.Label(win,text="",bg="#f1f5f9",fg="#526178",anchor="w"); status.pack(fill="x",padx=20,pady=(0,10))
        refresh()

