    def system_doctor(self):
        win=self.window("NevOS System Doctor","680x560"); win.configure(bg="#111827")
        tk.Label(win,text="SYSTEM DOCTOR",font=("Segoe UI",22,"bold"),bg="#111827",fg="#67e8f9").pack(anchor="w",padx=18,pady=12)
        out=tk.Text(win,bg="#0b1220",fg="#dbeafe",font=("Consolas",10),wrap="word"); out.pack(fill="both",expand=True,padx=14,pady=8)
        def scan():
            out.delete("1.0","end"); lines=[f"NevOS version: {NEVOS_VERSION}",f"Python: {sys.version.split()[0]}",f"Platform: {sys.platform}",f"Data folder: {self._data_dir()}",f"Disk root: {Path.home().anchor or Path.home()}",f"Installed app shortcuts: {len(self.apps)}", "", "Optional components:"]
            for mod in ("PIL","psutil","tkinterweb"):
                try: __import__(mod); lines.append(f"  {mod}: available")
                except ImportError: lines.append(f"  {mod}: not installed (optional)")
            try:
                import shutil as sh; total,used,free=sh.disk_usage(str(Path.home())); lines += ["",f"Disk total: {total//(1024**3)} GB",f"Disk used: {used//(1024**3)} GB",f"Disk free: {free//(1024**3)} GB"]
            except Exception as e: lines.append("Disk check unavailable: "+str(e))
            lines += ["", "Safety: NevOS is an app running inside Windows, not a replacement OS.","No files were deleted or changed by this scan."]
            out.insert("end","\n".join(lines))
        tk.Button(win,text="Run health check",command=scan,bg="#0891b2",fg="white",relief="flat",padx=12,pady=8).pack(pady=8); scan()

    def time_machine(self):
        win=self.window("NevOS Time Machine","650x480"); win.configure(bg="#111827")
        tk.Label(win,text="TIME MACHINE",font=("Segoe UI",22,"bold"),bg="#111827",fg="#67e8f9").pack(anchor="w",padx=18,pady=12)
        tk.Label(win,text="Back up NevOS local data to a ZIP, or restore a selected backup. Restoring overwrites matching files in the NevOS data folder.",wraplength=590,justify="left",bg="#111827",fg="#cbd5e1").pack(anchor="w",padx=18)
        area=tk.Text(win,bg="#0b1220",fg="#dbeafe",height=12); area.pack(fill="both",expand=True,padx=16,pady=12)
        def backup():
            path=filedialog.asksaveasfilename(parent=win,title="Create Time Machine backup",defaultextension=".zip",filetypes=[("ZIP backup","*.zip")])
            if not path:return
            try:
                folder=self._data_dir()
                with zipfile.ZipFile(path,"w",zipfile.ZIP_DEFLATED) as z:
                    for p in folder.rglob("*"):
                        if p.is_file(): z.write(p,p.relative_to(folder).as_posix())
                area.insert("end",f"Backup created: {path}\n")
            except Exception as e: messagebox.showerror("Backup failed",str(e),parent=win)
        def restore():
            path=filedialog.askopenfilename(parent=win,title="Choose backup",filetypes=[("ZIP backup","*.zip")])
            if not path:return
            if not messagebox.askyesno("Confirm restore","Restore files into NevOS data? Existing matching files may be overwritten.",parent=win):return
            try:
                dest=self._data_dir().resolve()
                with zipfile.ZipFile(path) as z:
                    names=z.namelist()
                    for name in names:
                        target=(dest/name).resolve()
                        if target!=dest and dest not in target.parents: raise ValueError("Backup contains an unsafe path.")
                    z.extractall(dest)
                area.insert("end",f"Restored backup: {path}\n")
            except Exception as e: messagebox.showerror("Restore failed",str(e),parent=win)
        tk.Button(win,text="Create backup ZIP",command=backup,bg="#0891b2",fg="white",relief="flat",padx=12,pady=8).pack(side="left",padx=16,pady=5)
        tk.Button(win,text="Restore backup…",command=restore,bg="#7c3aed",fg="white",relief="flat",padx=12,pady=8).pack(side="left",padx=5,pady=5)

