    def offline_vault(self):
        win=self.window("NevOS Offline Vault","720x560"); win.configure(bg="#111827")
        tk.Label(win,text="OFFLINE VAULT",font=("Segoe UI",22,"bold"),bg="#111827",fg="#67e8f9").pack(anchor="w",padx=16,pady=12)
        path=self._data_dir()/"vault.json"
        try: items=json.loads(path.read_text(encoding="utf-8"))
        except (OSError,ValueError): items=[]
        title=tk.Entry(win,font=("Segoe UI",11)); title.pack(fill="x",padx=16,pady=5); title.insert(0,"Note title")
        body=tk.Text(win,height=10,bg="#0b1220",fg="#e2e8f0"); body.pack(fill="both",expand=True,padx=16,pady=5)
        listing=tk.Listbox(win,height=7,bg="#1e293b",fg="white"); listing.pack(fill="x",padx=16,pady=5)
        def refresh(): listing.delete(0,"end"); [listing.insert("end",f"{i+1}. {x.get('title','Untitled')}") for i,x in enumerate(items)]
        def save_note():
            name=title.get().strip() or "Untitled"; text=body.get("1.0","end-1c").strip()
            if not text: messagebox.showinfo("Offline Vault","Write a note first.",parent=win); return
            items.append({"title":name,"body":text,"saved":datetime.now().isoformat(timespec="seconds")})
            try: path.write_text(json.dumps(items,ensure_ascii=False,indent=2),encoding="utf-8"); refresh(); body.delete("1.0","end"); title.delete(0,"end"); title.insert(0,"Note title")
            except OSError as e: messagebox.showerror("Save failed",str(e),parent=win)
        def load_note(_e=None):
            if listing.curselection():
                x=items[listing.curselection()[0]]; title.delete(0,"end"); title.insert(0,x.get("title","")); body.delete("1.0","end"); body.insert("1.0",x.get("body",""))
        def export_note():
            if not listing.curselection():return
            x=items[listing.curselection()[0]]; dest=filedialog.asksaveasfilename(parent=win,defaultextension=".txt",filetypes=[("Text file","*.txt")])
            if dest: Path(dest).write_text(x.get("title","")+"\n\n"+x.get("body",""),encoding="utf-8")
        buttons=tk.Frame(win,bg="#111827"); buttons.pack(fill="x",padx=16,pady=8)
        for label,cmd in [("Save note",save_note),("Load selected",load_note),("Export selected",export_note)]: tk.Button(buttons,text=label,command=cmd,bg="#1e293b",fg="white",relief="flat",padx=10,pady=6).pack(side="left",padx=4)
        listing.bind("<<ListboxSelect>>",load_note); refresh()

    def universal_launcher(self):
        win=self.window("NevOS Universal Launcher","540x600"); win.configure(bg="#111827")
        tk.Label(win,text="UNIVERSAL LAUNCHER",font=("Segoe UI",19,"bold"),bg="#111827",fg="#67e8f9").pack(anchor="w",padx=16,pady=12)
        query=tk.StringVar(); entry=tk.Entry(win,textvariable=query,font=("Segoe UI",13)); entry.pack(fill="x",padx=16,pady=5); listing=tk.Listbox(win,bg="#1e293b",fg="white",font=("Segoe UI",11),height=22); listing.pack(fill="both",expand=True,padx=16,pady=8)
        options=[("Tom AI 3.0",self.tom_ai),("Notepad",self.notepad),("Word",self.word),("Excel / Sheets",self.sheets),("PowerPoint / Slides",self.slides),("Calculator",self.calculator),("File Manager",self.files),("Browser",self.browser),("Paint Studio X",self.paint),("Calendar",self.calendar_app),("Chess",self.chess_app),("Store",self.store),("Security Center",self.security_center),("Recovery Center",self.recovery_center),("Quick Panel",self.quick_panel),("System Doctor",self.system_doctor),("Time Machine",self.time_machine),("Automation Studio",self.automation_studio),("Extension Center",self.extension_center),("Offline Vault",self.offline_vault),("Settings",self.settings),("Gaming Hub",self.gaming_hub)]
        def update(*_):
            listing.delete(0,"end"); term=query.get().lower()
            for name,_cmd in options:
                if term in name.lower(): listing.insert("end",name)
        def open_selected(_e=None):
            if not listing.curselection():return
            name=listing.get(listing.curselection()[0]); next(cmd for n,cmd in options if n==name)()
        query.trace_add("write",update); listing.bind("<Double-Button-1>",open_selected); entry.bind("<Return>",lambda e:(listing.selection_set(0),open_selected()) if listing.size() else None); update(); entry.focus_set()
        win.bind("<Control-space>",lambda e:self.universal_launcher())

