    def insider_center(self):
        """Local Insider/update dashboard. It does not pretend a server is configured."""
        win=self.window("NevOS Insider Update Center","780x650"); win.configure(bg="#080d1b")
        tk.Label(win,text="NEVOS INSIDER  /  MAJOR UPDATE CENTER",font=("Segoe UI",20,"bold"),bg="#080d1b",fg="#67e8f9").pack(anchor="w",padx=18,pady=(16,4))
        tk.Label(win,text=f"Installed build: {NEVOS_VERSION}    •    Channel and update settings are stored locally",bg="#080d1b",fg="#cbd5e1").pack(anchor="w",padx=20,pady=(0,12))
        card=tk.Frame(win,bg="#111d32",padx=14,pady=12); card.pack(fill="x",padx=16,pady=6)
        tk.Label(card,text="Release channel",bg="#111d32",fg="white",font=("Segoe UI",12,"bold")).pack(anchor="w")
        settings_path=self._data_dir()/"insider_settings.json"
        try: settings=json.loads(settings_path.read_text(encoding="utf-8"))
        except (OSError,ValueError): settings={}
        channel=tk.StringVar(value=settings.get("channel","beta")); behavior=tk.StringVar(value=settings.get("behavior","notify")); manifest=tk.StringVar(value=settings.get("manifest_url",""))
        ttk.Combobox(card,textvariable=channel,values=("stable","beta","canary"),state="readonly",width=18).pack(anchor="w",pady=5)
        tk.Label(card,text="Stable = tested releases • Beta = preview • Canary = experimental",bg="#111d32",fg="#94a3b8",wraplength=650).pack(anchor="w")
        tk.Label(card,text="Install policy",bg="#111d32",fg="white",font=("Segoe UI",11,"bold")).pack(anchor="w",pady=(12,2))
        ttk.Combobox(card,textvariable=behavior,values=("notify","download-ask-install"),state="readonly",width=24).pack(anchor="w")
        tk.Label(card,text="Release manifest URL (optional; HTTPS recommended)",bg="#111d32",fg="white").pack(anchor="w",pady=(12,2))
        tk.Entry(card,textvariable=manifest,width=78).pack(fill="x",anchor="w")
        status=tk.StringVar(value="No live update source configured." if not manifest.get().strip() else "A source is saved; use Check manifest to inspect it.")
        tk.Label(win,textvariable=status,bg="#080d1b",fg="#fbbf24",wraplength=720,justify="left").pack(anchor="w",padx=20,pady=8)
        log=tk.Text(win,height=10,bg="#0b1220",fg="#dbeafe",insertbackground="white",wrap="word"); log.pack(fill="both",expand=True,padx=16,pady=8)
        log.insert("end","Insider update safety\n• Never run a downloaded Python file automatically.\n• Review release notes and verify package hashes/signatures before installation.\n• The existing manual installer remains available in Settings → Updates.\n• A manifest check only reads metadata; it does not install anything.\n")
        def save():
            settings.update({"channel":channel.get(),"behavior":behavior.get(),"manifest_url":manifest.get().strip(),"backup_before_update":True})
            try: settings_path.write_text(json.dumps(settings,indent=2),encoding="utf-8"); status.set("Insider preferences saved locally.")
            except OSError as e: messagebox.showerror("Save failed",str(e),parent=win)
        def check():
            url=manifest.get().strip()
            if not url:
                status.set("No manifest URL set. Configure a trusted HTTPS JSON manifest URL first."); return
            if not url.lower().startswith("https://"):
                messagebox.showwarning("Update source","For safety, the manifest URL must use HTTPS.",parent=win); return
            if not messagebox.askyesno("Check update source","Connect to this URL to retrieve update metadata? No code will be downloaded or installed.\n\n"+url,parent=win): return
            import threading, urllib.request
            def worker():
                try:
                    req=urllib.request.Request(url,headers={"User-Agent":"NevOS-Insider/7"})
                    with urllib.request.urlopen(req,timeout=8) as response:
                        data=response.read(256*1024+1)
                    if len(data)>256*1024: raise ValueError("Manifest is larger than 256 KB.")
                    parsed=json.loads(data.decode("utf-8"))
                    if not isinstance(parsed,dict): raise ValueError("Manifest must be a JSON object.")
                    version=str(parsed.get("version","Unknown"))[:80]; notes=str(parsed.get("notes","No release notes provided."))[:4000]
                    def show():
                        status.set("Manifest fetched. Metadata only; nothing installed.")
                        log.insert("end",f"\nManifest version: {version}\nRelease notes:\n{notes}\n")
                    win.after(0,show)
                except Exception as e:
                    win.after(0,lambda:status.set("Manifest check failed: "+str(e)[:250]))
            status.set("Checking manifest…"); threading.Thread(target=worker,daemon=True).start()
        row=tk.Frame(win,bg="#080d1b"); row.pack(fill="x",padx=16,pady=(0,14))
        tk.Button(row,text="Save settings",command=save,bg="#155e75",fg="white",relief="flat",padx=12,pady=7).pack(side="left",padx=(0,6))
        tk.Button(row,text="Check manifest",command=check,bg="#1d4ed8",fg="white",relief="flat",padx=12,pady=7).pack(side="left",padx=6)
        tk.Button(row,text="Manual Update Installer",command=self.install_manual_update,bg="#334155",fg="white",relief="flat",padx=12,pady=7).pack(side="left",padx=6)

