    def focus_planner(self):
        win=self.window("NevOS Focus Planner","600x500"); win.configure(bg="#111827")
        tk.Label(win,text="FOCUS PLANNER",font=("Segoe UI",20,"bold"),bg="#111827",fg="#67e8f9").pack(anchor="w",padx=18,pady=(16,4))
        task=tk.Entry(win,font=("Segoe UI",12)); task.pack(fill="x",padx=18,pady=6); task.insert(0,"What do you want to focus on?")
        mins=tk.IntVar(value=25); tk.Label(win,text="Focus duration (minutes)",bg="#111827",fg="white").pack(anchor="w",padx=18,pady=(6,2)); ttk.Spinbox(win,from_=1,to=180,textvariable=mins,width=8).pack(anchor="w",padx=18)
        clock=tk.StringVar(value="Ready when you are"); tk.Label(win,textvariable=clock,font=("Segoe UI",22,"bold"),bg="#111827",fg="#a5f3fc").pack(pady=18)
        log=tk.Text(win,height=8,bg="#0b1220",fg="#dbeafe"); log.pack(fill="both",expand=True,padx=18,pady=6)
        state={"remaining":0,"after":None,"running":False}
        def tick():
            if not state["running"]: return
            state["remaining"]-=1
            if state["remaining"]<=0:
                state["running"]=False; clock.set("Session complete!"); self.notify("Focus Planner","Your focus session is complete."); log.insert("end","Completed: "+task.get().strip()+"\n"); return
            clock.set(f"{state['remaining']//60:02d}:{state['remaining']%60:02d}"); state["after"]=win.after(1000,tick)
        def start():
            if state["after"]:
                try: win.after_cancel(state["after"])
                except tk.TclError: pass
            state["remaining"]=max(1,int(mins.get()))*60; state["running"]=True; clock.set(f"{state['remaining']//60:02d}:{state['remaining']%60:02d}"); tick()
        def stop():
            state["running"]=False
            if state["after"]:
                try: win.after_cancel(state["after"])
                except tk.TclError: pass
            clock.set("Paused / stopped")
        row=tk.Frame(win,bg="#111827"); row.pack(pady=8)
        tk.Button(row,text="Start / Restart",command=start,bg="#0e7490",fg="white",relief="flat",padx=12,pady=7).pack(side="left",padx=4)
        tk.Button(row,text="Stop",command=stop,bg="#334155",fg="white",relief="flat",padx=12,pady=7).pack(side="left",padx=4)

