    def screenshot_studio(self):
        win=self.window("NevOS Screenshot Studio","560x360"); win.configure(bg="#111827")
        tk.Label(win,text="SCREENSHOT STUDIO",font=("Segoe UI",20,"bold"),bg="#111827",fg="#67e8f9").pack(anchor="w",padx=18,pady=(16,8))
        tk.Label(win,text="Capture the NevOS application window after choosing a save location. On some systems, screenshots may require Pillow.",wraplength=510,justify="left",bg="#111827",fg="#cbd5e1").pack(anchor="w",padx=18,pady=8)
        def capture():
            dest=filedialog.asksaveasfilename(parent=win,defaultextension=".png",filetypes=[("PNG image","*.png")])
            if not dest:return
            try:
                from PIL import ImageGrab
                self.root.update_idletasks(); x=self.root.winfo_rootx(); y=self.root.winfo_rooty(); w=self.root.winfo_width(); h=self.root.winfo_height()
                ImageGrab.grab(bbox=(x,y,x+w,y+h)).save(dest); messagebox.showinfo("Screenshot",f"Saved screenshot to:\n{dest}",parent=win)
            except ImportError: messagebox.showwarning("Pillow required","Install Pillow with: py -m pip install pillow",parent=win)
            except Exception as e: messagebox.showerror("Screenshot failed",str(e),parent=win)
        tk.Button(win,text="Capture NevOS window…",command=capture,bg="#0e7490",fg="white",relief="flat",padx=12,pady=8).pack(anchor="w",padx=18,pady=12)

    def smart_clipboard(self):
        win=self.window("NevOS Smart Clipboard","620x520"); win.configure(bg="#111827")
        tk.Label(win,text="SMART CLIPBOARD",font=("Segoe UI",20,"bold"),bg="#111827",fg="#67e8f9").pack(anchor="w",padx=18,pady=(16,6))
        tk.Label(win,text="Local clipboard snippets only; this tool does not monitor everything you copy.",bg="#111827",fg="#cbd5e1").pack(anchor="w",padx=18,pady=(0,8))
        listing=tk.Listbox(win,bg="#0b1220",fg="white",selectbackground="#155e75"); listing.pack(fill="both",expand=True,padx=18,pady=8)
        path=self.clipboard_history_path
        try: items=json.loads(path.read_text(encoding="utf-8"))
        except (OSError,ValueError): items=[]
        def refresh(): listing.delete(0,"end"); [listing.insert("end",str(x)[:120].replace("\n"," ")) for x in items]
        def capture():
            try: value=win.clipboard_get()
            except tk.TclError: messagebox.showinfo("Clipboard","The clipboard does not contain text.",parent=win); return
            if value.strip(): items.insert(0,value[:5000]); del items[50:]; path.write_text(json.dumps(items,ensure_ascii=False,indent=2),encoding="utf-8"); refresh()
        def copy_back():
            if not listing.curselection():return
            win.clipboard_clear(); win.clipboard_append(items[listing.curselection()[0]]); win.update(); messagebox.showinfo("Clipboard","Selected snippet copied.",parent=win)
        def clear():
            if messagebox.askyesno("Clear history","Delete all saved clipboard snippets?",parent=win): items.clear(); path.write_text("[]",encoding="utf-8"); refresh()
        row=tk.Frame(win,bg="#111827"); row.pack(fill="x",padx=18,pady=(0,14))
        for label,cmd in [("Capture current clipboard",capture),("Copy selected",copy_back),("Clear history",clear)]: tk.Button(row,text=label,command=cmd,bg="#334155",fg="white",relief="flat",padx=8,pady=7).pack(side="left",padx=3)
        refresh()

    def universal_search(self):
        win=self.window("NevOS Universal Search","650x560"); win.configure(bg="#111827")
        tk.Label(win,text="UNIVERSAL SEARCH",font=("Segoe UI",20,"bold"),bg="#111827",fg="#67e8f9").pack(anchor="w",padx=18,pady=(16,6))
        tk.Label(win,text="Searches app names and filenames in folders you choose. It does not index your entire computer automatically.",wraplength=610,justify="left",bg="#111827",fg="#cbd5e1").pack(anchor="w",padx=18,pady=(0,8))
        query=tk.StringVar(); entry=tk.Entry(win,textvariable=query,font=("Segoe UI",12)); entry.pack(fill="x",padx=18,pady=6)
        listing=tk.Listbox(win,bg="#0b1220",fg="white",selectbackground="#155e75",height=18); listing.pack(fill="both",expand=True,padx=18,pady=8)
        results=[]
        appnames=[x[1] for x in self.apps]
        def search():
            term=query.get().strip().lower(); listing.delete(0,"end"); results.clear()
            if not term:return
            for name in appnames:
                if term in name.lower(): results.append(("app",name)); listing.insert("end","APP  ·  "+name)
            if messagebox.askyesno("Search files","Choose a folder to search for matching filenames?",parent=win):
                folder=filedialog.askdirectory(parent=win,title="Choose folder to search")
                if folder:
                    count=0
                    try:
                        for root,dirs,files in os.walk(folder):
                            dirs[:]=[d for d in dirs if d not in (".git","__pycache__","node_modules")]
                            for fname in files:
                                if term in fname.lower(): results.append(("file",os.path.join(root,fname))); listing.insert("end","FILE · "+os.path.join(root,fname)); count+=1
                                if count>=500: raise StopIteration
                    except StopIteration: listing.insert("end","(Limited to 500 matching files)")
        def open_result(_e=None):
            if not listing.curselection():return
            typ,value=results[listing.curselection()[0]]
            if typ=="app":
                found=next((x for x in self.apps if x[1]==value),None)
                if found: found[2]()
            else:
                try: os.startfile(value) if hasattr(os,"startfile") else webbrowser.open(Path(value).resolve().as_uri())
                except Exception as e: messagebox.showerror("Open file",str(e),parent=win)
        row=tk.Frame(win,bg="#111827"); row.pack(fill="x",padx=18,pady=(0,14))
        tk.Button(row,text="Search",command=search,bg="#0e7490",fg="white",relief="flat",padx=12,pady=7).pack(side="left",padx=4)
        tk.Button(row,text="Open selected",command=open_result,bg="#334155",fg="white",relief="flat",padx=12,pady=7).pack(side="left",padx=4)
        listing.bind("<Double-Button-1>",open_result); entry.bind("<Return>",lambda e:search()); entry.focus_set()


    # NevOS 9.0 Aurora additions. Cloud and AI features are intentionally local-first.
    def ai_command_center(self):
        win=self.window("AI Command Center","720x560"); win.configure(bg="#0b1220")
        tk.Label(win,text="NEVOS COMMAND CENTER",font=("Segoe UI",20,"bold"),bg="#0b1220",fg="#7dd3fc").pack(anchor="w",padx=18,pady=(16,4))
        tk.Label(win,text="Local command helper. This prototype does not contact an AI service.",bg="#0b1220",fg="#cbd5e1").pack(anchor="w",padx=18)
        out=tk.Text(win,bg="#111827",fg="#e5e7eb",insertbackground="white",wrap="word",height=18); out.pack(fill="both",expand=True,padx=18,pady=10)
        out.insert("end","Hi! Try: open Notepad, open DBMS, search, open settings, show data folder, or help.\n\n")
        entry=tk.Entry(win,bg="#1f2937",fg="white",insertbackground="white",font=("Segoe UI",12)); entry.pack(fill="x",padx=18,pady=(0,8))
        def run(_event=None):
            q=entry.get().strip(); entry.delete(0,"end")
            if not q:return
            out.insert("end",f"You: {q}\n")
            low=q.lower(); answer="I don't know that local command yet. Type help for supported commands."
            if low in ("help","what can you do?"): answer="Commands: open <app>, search, open settings, show data folder, show version. This is a local command router, not a generative AI model."
            elif low.startswith("open "):
                target=low[5:].strip(); found=next((a for a in self.apps if target in a[1].lower() or target in a[0].lower()),None)
                if found: answer=f"Opening {found[1]}…"; out.insert("end",f"Tom: {answer}\n\n"); found[2](); return
                answer="I couldn't find that app. Try Universal Search."
            elif "search" in low: answer="Opening Universal Search…"; out.insert("end",f"Tom: {answer}\n\n"); self.universal_search(); return
            elif "setting" in low: answer="Opening Settings…"; out.insert("end",f"Tom: {answer}\n\n"); self.settings(); return
            elif "data folder" in low: answer=str(self._data_dir())
            elif "version" in low: answer=f"NevOS {NEVOS_VERSION}"
            out.insert("end",f"Tom: {answer}\n\n"); out.see("end")
        row=tk.Frame(win,bg="#0b1220"); row.pack(fill="x",padx=18,pady=(0,14))
        tk.Button(row,text="Run command",command=run,bg="#0369a1",fg="white",relief="flat",padx=12,pady=7).pack(side="left")
        entry.bind("<Return>",run); entry.focus_set()

    def nevos_dbms(self):
        folder=self._data_dir()/"databases"; folder.mkdir(parents=True,exist_ok=True)
        try: import sqlite3
        except Exception as e: messagebox.showerror("DBMS",str(e)); return
        win=self.window("NevOS DBMS","1000x650"); win.configure(bg="#0b1220")
        tk.Label(win,text="NevOS DBMS · SQLite",font=("Segoe UI",18,"bold"),bg="#0b1220",fg="#7dd3fc").pack(anchor="w",padx=14,pady=10)
        top=tk.Frame(win,bg="#0b1220"); top.pack(fill="x",padx=14)
        current={"conn":None,"path":None}
        dbvar=tk.StringVar(value="No database open")
        tk.Label(top,textvariable=dbvar,bg="#0b1220",fg="#e5e7eb").pack(side="left",padx=6)
        body=tk.PanedWindow(win,orient="horizontal",bg="#334155",sashwidth=5); body.pack(fill="both",expand=True,padx=14,pady=10)
        left=tk.Frame(body,bg="#111827",width=220); body.add(left)
        tk.Label(left,text="Tables",bg="#111827",fg="white").pack(anchor="w",padx=8,pady=5)
        tables=tk.Listbox(left,bg="#0f172a",fg="white",selectbackground="#0369a1"); tables.pack(fill="both",expand=True,padx=6,pady=6)
        right=tk.Frame(body,bg="#111827"); body.add(right)
        grid=ttk.Treeview(right,show="headings",height=12); grid.pack(fill="both",expand=True,padx=6,pady=6)
        tk.Label(right,text="SQL Query (SQLite)",bg="#111827",fg="#7dd3fc").pack(anchor="w",padx=6)
        sql=tk.Text(right,height=5,bg="#020617",fg="#e2e8f0",insertbackground="white"); sql.pack(fill="x",padx=6,pady=4)
        result=tk.Text(right,height=5,bg="#020617",fg="#a7f3d0",insertbackground="white"); result.pack(fill="x",padx=6,pady=4)
        def refresh_tables():
            tables.delete(0,"end")
            if not current["conn"]:return
            try:
                rows=current["conn"].execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name").fetchall()
                for r in rows: tables.insert("end",r[0])
            except Exception as e: messagebox.showerror("DBMS",str(e),parent=win)
        def show_table(_e=None):
            if not current["conn"] or not tables.curselection():return
            name=tables.get(tables.curselection()[0]); safe='"'+name.replace('"','""')+'"'
            try:
                cur=current["conn"].execute(f"SELECT * FROM {safe} LIMIT 500"); rows=cur.fetchall(); cols=[d[0] for d in cur.description or []]
                grid.delete(*grid.get_children()); grid["columns"]=cols
                for c in cols:grid.heading(c,text=c); grid.column(c,width=120,stretch=True)
                for r in rows:grid.insert("","end",values=[str(v) if v is not None else "NULL" for v in r])
                result.delete("1.0","end"); result.insert("end",f"{len(rows)} row(s) shown from {name}")
            except Exception as e:messagebox.showerror("DBMS",str(e),parent=win)
        def new_db():
            path=filedialog.asksaveasfilename(parent=win,initialdir=folder,defaultextension=".db",filetypes=[("SQLite database","*.db *.sqlite" )])
            if not path:return
            try:
                if current["conn"]:current["conn"].close()
                current["conn"]=sqlite3.connect(path); current["path"]=path; dbvar.set(path); refresh_tables()
            except Exception as e:messagebox.showerror("DBMS",str(e),parent=win)
        def open_db():
            path=filedialog.askopenfilename(parent=win,initialdir=folder,filetypes=[("SQLite database","*.db *.sqlite *.sqlite3"),("All files","*.*")])
            if not path:return
            try:
                if current["conn"]:current["conn"].close()
                current["conn"]=sqlite3.connect(path); current["path"]=path; dbvar.set(path); refresh_tables()
            except Exception as e:messagebox.showerror("DBMS",str(e),parent=win)
        def create_table():
            if not current["conn"]:messagebox.showinfo("DBMS","Create or open a database first.",parent=win);return
            name=simpledialog.askstring("New table","Table name:",parent=win)
            if not name or not name.replace("_","").isalnum():messagebox.showwarning("DBMS","Use letters, numbers, and underscores for table names.",parent=win);return
            try:current["conn"].execute('CREATE TABLE "'+name+'" (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, notes TEXT)');current["conn"].commit();refresh_tables()
            except Exception as e:messagebox.showerror("DBMS",str(e),parent=win)
        def run_sql():
            if not current["conn"]:messagebox.showinfo("DBMS","Create or open a database first.",parent=win);return
            statement=sql.get("1.0","end").strip()
            if not statement:return
            try:
                cur=current["conn"].execute(statement); rows=cur.fetchall() if cur.description else []; current["conn"].commit()
                result.delete("1.0","end")
                if cur.description: result.insert("end"," | ".join(d[0] for d in cur.description)+"\n"+"\n".join(" | ".join(str(v) for v in r) for r in rows[:300]))
                else:result.insert("end",f"SQL executed successfully. Rows changed: {current['conn'].total_changes}")
                refresh_tables()
            except Exception as e:messagebox.showerror("SQL error",str(e),parent=win)
        for label,cmd in [("New DB",new_db),("Open DB",open_db),("New Table",create_table),("Refresh",refresh_tables),("Run SQL",run_sql)]:tk.Button(top,text=label,command=cmd,bg="#1e3a5f",fg="white",relief="flat",padx=9,pady=5).pack(side="left",padx=3)
        tables.bind("<<ListboxSelect>>",show_table)
        sql.insert("1.0","SELECT name FROM sqlite_master WHERE type='table';")
        def close_db():
            try:
                if current["conn"]:current["conn"].close()
            except Exception:pass
            win.destroy()
        win.protocol("WM_DELETE_WINDOW",close_db)

    def nevos_cloud(self):
        root=self._data_dir()/"cloud_mirror"; root.mkdir(parents=True,exist_ok=True)
        win=self.window("NevOS Cloud","700x500"); win.configure(bg="#0b1220")
        tk.Label(win,text="NevOS Cloud · Local Sync Folder",font=("Segoe UI",18,"bold"),bg="#0b1220",fg="#7dd3fc").pack(anchor="w",padx=18,pady=(16,6))
        tk.Label(win,text="This first version is a local mirror folder, not internet cloud storage. Copy selected files into it and back up the folder yourself.",wraplength=650,justify="left",bg="#0b1220",fg="#cbd5e1").pack(anchor="w",padx=18)
        listing=tk.Listbox(win,bg="#111827",fg="white"); listing.pack(fill="both",expand=True,padx=18,pady=12)
        def refresh():listing.delete(0,"end");[listing.insert("end",p.name) for p in sorted(root.iterdir())]
        def add_files():
            paths=filedialog.askopenfilenames(parent=win,title="Choose files to copy into NevOS Cloud")
            for src in paths:
                try:
                    dst=root/Path(src).name
                    if dst.exists() and not messagebox.askyesno("Replace file?",f"{dst.name} already exists. Replace it?",parent=win):continue
                    shutil.copy2(src,dst)
                except Exception as e:messagebox.showerror("Cloud copy",f"{src}\n{e}",parent=win)
            refresh()
        def restore():
            if not listing.curselection():return
            src=root/listing.get(listing.curselection()[0]); dest=filedialog.askdirectory(parent=win,title="Choose destination folder")
            if dest:
                try:shutil.copy2(src,Path(dest)/src.name);messagebox.showinfo("Cloud copy","File copied to destination.",parent=win)
                except Exception as e:messagebox.showerror("Cloud copy",str(e),parent=win)
        row=tk.Frame(win,bg="#0b1220");row.pack(fill="x",padx=18,pady=(0,14))
        for label,cmd in [("Add files",add_files),("Restore selected",restore),("Open folder",lambda:os.startfile(root) if hasattr(os,"startfile") else webbrowser.open(root.as_uri()))]:tk.Button(row,text=label,command=cmd,bg="#1e3a5f",fg="white",relief="flat",padx=10,pady=7).pack(side="left",padx=4)
        refresh()

    def quick_share(self):
        win=self.window("Quick Share","650x460");win.configure(bg="#0b1220")
        tk.Label(win,text="QUICK SHARE",font=("Segoe UI",20,"bold"),bg="#0b1220",fg="#7dd3fc").pack(anchor="w",padx=18,pady=(16,6))
        tk.Label(win,text="Create a portable ZIP bundle of selected files to share using USB, email, or your preferred transfer app.",wraplength=600,justify="left",bg="#0b1220",fg="#cbd5e1").pack(anchor="w",padx=18)
        selected=tk.Listbox(win,bg="#111827",fg="white",height=12);selected.pack(fill="both",expand=True,padx=18,pady=10);paths=[]
        def add():
            for pth in filedialog.askopenfilenames(parent=win):
                if pth not in paths:paths.append(pth);selected.insert("end",pth)
        def remove():
            idx=selected.curselection()
            if idx:paths.pop(idx[0]);selected.delete(idx[0])
        def export():
            if not paths:messagebox.showinfo("Quick Share","Add at least one file.",parent=win);return
            dest=filedialog.asksaveasfilename(parent=win,defaultextension=".zip",initialfile="NevOS-Share.zip",filetypes=[("ZIP archive","*.zip")])
            if not dest:return
            try:
                with zipfile.ZipFile(dest,"w",zipfile.ZIP_DEFLATED) as z:
                    for item in paths:z.write(item,arcname=Path(item).name)
                messagebox.showinfo("Quick Share",f"Share bundle created:\n{dest}",parent=win)
            except Exception as e:messagebox.showerror("Quick Share",str(e),parent=win)
        row=tk.Frame(win,bg="#0b1220");row.pack(fill="x",padx=18,pady=(0,14))
        for label,cmd in [("Add files",add),("Remove selected",remove),("Create share ZIP",export)]:tk.Button(row,text=label,command=cmd,bg="#1e3a5f",fg="white",relief="flat",padx=10,pady=7).pack(side="left",padx=4)

