    def screen_recorder(self):
        win=self.window("Screen Recorder","600x420");win.configure(bg="#0b1220")
        tk.Label(win,text="SCREEN RECORDER",font=("Segoe UI",20,"bold"),bg="#0b1220",fg="#7dd3fc").pack(anchor="w",padx=18,pady=(16,6))
        tk.Label(win,text="Records screen frames to an animated GIF. Requires Pillow (pip install pillow). Recording captures the visible desktop, so close private windows first.",wraplength=550,justify="left",bg="#0b1220",fg="#cbd5e1").pack(anchor="w",padx=18)
        status=tk.StringVar(value="Ready. Choose a GIF path and duration.");tk.Label(win,textvariable=status,bg="#0b1220",fg="#a7f3d0",wraplength=550).pack(anchor="w",padx=18,pady=10)
        dur=tk.StringVar(value="5");row=tk.Frame(win,bg="#0b1220");row.pack(anchor="w",padx=18,pady=5);tk.Label(row,text="Duration (seconds, max 20):",bg="#0b1220",fg="white").pack(side="left");tk.Entry(row,textvariable=dur,width=6).pack(side="left",padx=8)
        def record():
            try:from PIL import ImageGrab
            except ImportError:messagebox.showerror("Screen Recorder","Pillow is required. Install it with: py -m pip install pillow",parent=win);return
            dest=filedialog.asksaveasfilename(parent=win,defaultextension=".gif",filetypes=[("Animated GIF","*.gif")])
            if not dest:return
            try:seconds=max(1,min(20,int(dur.get())))
            except ValueError:messagebox.showwarning("Screen Recorder","Duration must be a number.",parent=win);return
            frames=[];status.set("Recording… keep this window open.")
            def capture(i=0):
                try:
                    frames.append(ImageGrab.grab().convert("P",palette=1))
                    if i+1<seconds*2:win.after(500,lambda:capture(i+1))
                    else:
                        frames[0].save(dest,save_all=True,append_images=frames[1:],duration=500,loop=0,optimize=True);status.set(f"Saved {len(frames)} frames to {dest}");messagebox.showinfo("Screen Recorder","GIF recording saved.",parent=win)
                except Exception as e:status.set("Recording failed");messagebox.showerror("Screen Recorder",str(e),parent=win)
            capture()
        tk.Button(win,text="Record GIF",command=record,bg="#0369a1",fg="white",relief="flat",padx=12,pady=8).pack(anchor="w",padx=18,pady=8)



