    def spotlight_search_plus(self):
        win=self.window("Spotlight Search Plus", "760x560"); win.configure(bg="#0b1220")
        tk.Label(win,text="SPOTLIGHT SEARCH",font=("Segoe UI",20,"bold"),bg="#0b1220",fg="#93c5fd").pack(anchor="w",padx=18,pady=(16,8))
        query=tk.StringVar(); entry=tk.Entry(win,textvariable=query,font=("Segoe UI",14),bg="#1e293b",fg="white",insertbackground="white"); entry.pack(fill="x",padx=18,pady=(0,10))
        results=tk.Listbox(win,bg="#111827",fg="#e5e7eb",selectbackground="#2563eb",font=("Segoe UI",11)); results.pack(fill="both",expand=True,padx=18,pady=(0,12))
        found=[]
        def run(_e=None):
            nonlocal found
            term=query.get().strip().lower(); results.delete(0,"end"); found=[]
            if not term: return
            for item in self.apps:
                if term in item[0].lower() or term in item[1].lower(): found.append(("app",item[1],item[2])); results.insert("end","APP   "+item[1])
            try:
                base=Path.home()
                for p in base.rglob("*"):
                    if len(found)>=150: break
                    if p.is_file() and term in p.name.lower() and ".nevos7" not in str(p).lower(): found.append(("file",str(p),None)); results.insert("end","FILE  "+p.name+"  —  "+str(p.parent))
            except (OSError, PermissionError): pass
        def open_selected():
            if not results.curselection(): return
            kind,value,fn=found[results.curselection()[0]]
            if kind=="app": fn()
            else:
                try: os.startfile(value) if hasattr(os,"startfile") else webbrowser.open(Path(value).as_uri())
                except Exception as e: messagebox.showerror("Spotlight",str(e),parent=win)
        row=tk.Frame(win,bg="#0b1220"); row.pack(fill="x",padx=18,pady=(0,14))
        tk.Button(row,text="Search",command=run,bg="#2563eb",fg="white",relief="flat",padx=14,pady=7).pack(side="left",padx=4)
        tk.Button(row,text="Open selected",command=open_selected,bg="#334155",fg="white",relief="flat",padx=14,pady=7).pack(side="left",padx=4)
        entry.bind("<Return>",run); results.bind("<Double-Button-1>",lambda e:open_selected()); entry.focus_set()

