    def time_machine_backups(self):
        import time
        base=self._data_dir(); backup_root=base/"backups"; backup_root.mkdir(parents=True,exist_ok=True)
        win=self.window("Time Machine — Backups", "760x520"); win.configure(bg="#0b1220")
        tk.Label(win,text="TIME MACHINE",font=("Segoe UI",20,"bold"),bg="#0b1220",fg="#93c5fd").pack(anchor="w",padx=18,pady=(16,4))
        tk.Label(win,text="Creates ZIP snapshots of NevOS data. Restore extracts files into the NevOS data folder; make a fresh backup first.",wraplength=700,justify="left",bg="#0b1220",fg="#cbd5e1").pack(anchor="w",padx=18,pady=(0,10))
        listing=tk.Listbox(win,bg="#111827",fg="white",selectbackground="#2563eb"); listing.pack(fill="both",expand=True,padx=18,pady=8)
        def refresh():
            listing.delete(0,"end")
            for p in sorted(backup_root.glob("NevOS_Backup_*.zip"),key=lambda p:p.stat().st_mtime,reverse=True): listing.insert("end",p.name)
        def create():
            stamp=datetime.now().strftime("%Y%m%d_%H%M%S"); dest=backup_root/f"NevOS_Backup_{stamp}.zip"
            try:
                with zipfile.ZipFile(dest,"w",zipfile.ZIP_DEFLATED) as z:
                    for p in base.rglob("*"):
                        if p.is_file() and backup_root not in p.parents and p!=dest:
                            try:z.write(p,p.relative_to(base))
                            except OSError:pass
                refresh(); messagebox.showinfo("Backup",f"Backup created:\n{dest}",parent=win)
            except Exception as e: messagebox.showerror("Backup failed",str(e),parent=win)
        def restore():
            if not listing.curselection(): messagebox.showinfo("Restore","Select a backup first.",parent=win); return
            name=listing.get(listing.curselection()[0]); path=backup_root/name
            if not messagebox.askyesno("Confirm restore","Restore files from this backup into NevOS data? Existing files with the same names may be replaced.",parent=win): return
            try:
                with zipfile.ZipFile(path) as z:
                    for member in z.infolist():
                        target=(base/member.filename).resolve()
                        if base.resolve() not in target.parents and target!=base.resolve(): raise ValueError("Unsafe path in backup")
                    z.extractall(base)
                messagebox.showinfo("Restore","Backup files restored. Restart NevOS if needed.",parent=win)
            except Exception as e: messagebox.showerror("Restore failed",str(e),parent=win)
        row=tk.Frame(win,bg="#0b1220"); row.pack(fill="x",padx=18,pady=(0,14))
        tk.Button(row,text="Create backup",command=create,bg="#2563eb",fg="white",relief="flat",padx=12,pady=7).pack(side="left",padx=4)
        tk.Button(row,text="Restore selected",command=restore,bg="#b45309",fg="white",relief="flat",padx=12,pady=7).pack(side="left",padx=4)
        tk.Button(row,text="Refresh",command=refresh,bg="#334155",fg="white",relief="flat",padx=12,pady=7).pack(side="left",padx=4); refresh()

    def developer_lab_plus(self):
        win=self.window("Developer Lab", "900x650"); win.configure(bg="#0b1220")
        tk.Label(win,text="DEVELOPER LAB",font=("Segoe UI",20,"bold"),bg="#0b1220",fg="#93c5fd").pack(anchor="w",padx=16,pady=(14,6))
        editor=tk.Text(win,bg="#020617",fg="#e2e8f0",insertbackground="white",font=("Consolas",11),undo=True); editor.pack(fill="both",expand=True,padx=16,pady=8)
        editor.insert("1.0","# NevOS Developer Lab\nprint('Hello from NevOS!')\n")
        status=tk.StringVar(value="Write Python, check syntax, then save or run your script."); tk.Label(win,textvariable=status,bg="#0b1220",fg="#cbd5e1",wraplength=850).pack(anchor="w",padx=16)
        def load():
            path=filedialog.askopenfilename(parent=win,filetypes=[("Python files","*.py"),("All files","*.*")])
            if path:
                try: editor.delete("1.0","end"); editor.insert("1.0",Path(path).read_text(encoding="utf-8")); status.set(path); win.current_path=path
                except Exception as e:messagebox.showerror("Open",str(e),parent=win)
        def check():
            try:ast.parse(editor.get("1.0","end-1c")); status.set("Syntax check passed."); messagebox.showinfo("Developer Lab","Python syntax is valid.",parent=win)
            except SyntaxError as e:status.set(f"Syntax error on line {e.lineno}: {e.msg}"); messagebox.showerror("Syntax error",status.get(),parent=win)
        def save():
            path=filedialog.asksaveasfilename(parent=win,defaultextension=".py",filetypes=[("Python files","*.py")])
            if path:
                try:Path(path).write_text(editor.get("1.0","end-1c"),encoding="utf-8"); win.current_path=path; status.set("Saved: "+path)
                except Exception as e:messagebox.showerror("Save",str(e),parent=win)
        def run():
            path=getattr(win,"current_path",None)
            if not path:
                messagebox.showinfo("Run script","Save your script first.",parent=win); return
            if not messagebox.askyesno("Run Python script","This will execute your code with your Windows user permissions. Only run code you trust.",parent=win):return
            try:
                import subprocess
                subprocess.Popen([sys.executable,path],cwd=str(Path(path).parent)); status.set("Launched script in a separate process.")
            except Exception as e:messagebox.showerror("Run",str(e),parent=win)
        row=tk.Frame(win,bg="#0b1220"); row.pack(fill="x",padx=16,pady=12)
        for label,fn in [("Open",load),("Check syntax",check),("Save as",save),("Run saved script",run)]:tk.Button(row,text=label,command=fn,bg="#1d4ed8" if label!="Run saved script" else "#b45309",fg="white",relief="flat",padx=12,pady=7).pack(side="left",padx=4)

    def voice_assistant(self):
        win=self.window("Voice Assistant", "620x430"); win.configure(bg="#0b1220")
        tk.Label(win,text="VOICE ASSISTANT",font=("Segoe UI",20,"bold"),bg="#0b1220",fg="#93c5fd").pack(anchor="w",padx=18,pady=(16,6))
        tk.Label(win,text="Optional speech recognition uses the SpeechRecognition and microphone audio packages. If they are unavailable, type a command below.",wraplength=570,justify="left",bg="#0b1220",fg="#cbd5e1").pack(anchor="w",padx=18)
        command=tk.StringVar(); entry=tk.Entry(win,textvariable=command,font=("Segoe UI",12),bg="#1e293b",fg="white",insertbackground="white"); entry.pack(fill="x",padx=18,pady=12)
        status=tk.StringVar(value="Try: open Notepad, open DBMS, search, or open settings."); tk.Label(win,textvariable=status,wraplength=570,bg="#0b1220",fg="#a7f3d0").pack(anchor="w",padx=18,pady=4)
        def dispatch(text):
            low=text.lower().strip(); status.set("Command: "+text)
            if low.startswith("open "):
                term=low[5:]; item=next((a for a in self.apps if term in a[1].lower() or term in a[0].lower()),None)
                if item:item[2]()
                else:status.set("App not found. Try Spotlight Search Plus.")
            elif "search" in low:self.spotlight_search_plus()
            elif "settings" in low:self.settings()
            elif "backup" in low:self.time_machine_backups()
            else:status.set("Command not recognized. Try: open Notepad, open DBMS, search, open settings, or backup.")
        def typed(): dispatch(command.get())
        def listen():
            try: import speech_recognition as sr
            except ImportError: messagebox.showinfo("Voice Assistant","Install optional packages with:\npy -m pip install SpeechRecognition\nA microphone backend such as PyAudio may also be required.",parent=win); return
            status.set("Listening… allow microphone access.")
            def worker():
                try:
                    recognizer=sr.Recognizer()
                    with sr.Microphone() as mic:
                        audio=recognizer.listen(mic,timeout=5,phrase_time_limit=6)
                    phrase=recognizer.recognize_google(audio)
                    win.after(0,lambda:(command.set(phrase),dispatch(phrase)))
                except Exception as e: win.after(0,lambda:status.set("Voice input failed: "+str(e)))
            import threading; threading.Thread(target=worker,daemon=True).start()
        row=tk.Frame(win,bg="#0b1220"); row.pack(anchor="w",padx=18,pady=8)
        tk.Button(row,text="Run typed command",command=typed,bg="#2563eb",fg="white",relief="flat",padx=12,pady=7).pack(side="left",padx=4)
        tk.Button(row,text="Listen",command=listen,bg="#0e7490",fg="white",relief="flat",padx=12,pady=7).pack(side="left",padx=4)
        entry.bind("<Return>",lambda e:typed())

