    def safe_update_center(self):
        win=self.window("Safe Update Center", "700x470"); win.configure(bg="#0b1220")
        tk.Label(win,text="SAFE UPDATE CENTER",font=("Segoe UI",20,"bold"),bg="#0b1220",fg="#93c5fd").pack(anchor="w",padx=18,pady=(16,6))
        tk.Label(win,text="This build does not download or install updates automatically. Use backup and local source validation before replacing files.",wraplength=650,justify="left",bg="#0b1220",fg="#cbd5e1").pack(anchor="w",padx=18)
        out=tk.Text(win,bg="#111827",fg="#e5e7eb",height=13); out.pack(fill="both",expand=True,padx=18,pady=10)
        def check():
            out.delete("1.0","end"); out.insert("end",f"Installed version: {NEVOS_VERSION}\nPython: {sys.version.split()[0]}\nData folder: {self._data_dir()}\n\nNo online update server is configured.\nUse 'Validate local Python file' to parse a chosen source file.\n")
        def validate():
            path=filedialog.askopenfilename(parent=win,filetypes=[("Python source","*.py")])
            if not path:return
            try:
                code=Path(path).read_text(encoding="utf-8"); ast.parse(code); digest=hashlib.sha256(code.encode("utf-8")).hexdigest()
                messagebox.showinfo("Validation passed",f"Python syntax valid.\nSHA-256: {digest}",parent=win)
            except Exception as e:messagebox.showerror("Validation failed",str(e),parent=win)
        row=tk.Frame(win,bg="#0b1220"); row.pack(anchor="w",padx=18,pady=(0,14))
        tk.Button(row,text="Check status",command=check,bg="#2563eb",fg="white",relief="flat",padx=12,pady=7).pack(side="left",padx=4)
        tk.Button(row,text="Validate local Python file",command=validate,bg="#334155",fg="white",relief="flat",padx=12,pady=7).pack(side="left",padx=4); check()

