        search=tk.StringVar(); ent=tk.Entry(win,textvariable=search,font=("Segoe UI",11),relief="flat",bg="white"); ent.pack(fill="x",padx=20,pady=6,ipady=7)
        body=tk.Frame(win,bg="#f3f6fb"); body.pack(fill="both",expand=True,padx=18,pady=8)
        canvas=tk.Canvas(body,bg="#f3f6fb",highlightthickness=0); scroll=ttk.Scrollbar(body,orient="vertical",command=canvas.yview); inner=tk.Frame(canvas,bg="#f3f6fb")
        inner.bind("<Configure>",lambda e:canvas.configure(scrollregion=canvas.bbox("all")))
        canvas.create_window((0,0),window=inner,anchor="nw"); canvas.configure(yscrollcommand=scroll.set); canvas.pack(side="left",fill="both",expand=True); scroll.pack(side="right",fill="y")
        def render(*_):
            for child in inner.winfo_children(): child.destroy()
