    def _open_path(self, path):
        try:
            p=Path(path); p.mkdir(parents=True,exist_ok=True)
            if sys.platform.startswith("win"): os.startfile(str(p))
            elif sys.platform == "darwin": import subprocess; subprocess.Popen(["open",str(p)])
            else: import subprocess; subprocess.Popen(["xdg-open",str(p)])
        except Exception as exc:
            messagebox.showerror("Open folder",f"Could not open folder:\n{exc}",parent=self.root)

