    def user_profiles(self):
        """Manage local simulator profiles; these are not Windows accounts."""
        win=self.window("NevOS User Profiles", "720x520"); win.configure(bg="#f1f5f9")
        tk.Label(win,text="User Profiles",font=("Segoe UI",22,"bold"),bg="#f1f5f9",fg="#172238").pack(anchor="w",padx=20,pady=(16,4))
        tk.Label(win,text="Create and switch NevOS-local profiles. This does not create or change Windows accounts.",wraplength=670,bg="#f1f5f9",fg="#526178").pack(anchor="w",padx=20,pady=(0,12))
        path=self._data_dir()/"user_profiles.json"
        def load():
            try:
                data=json.loads(path.read_text(encoding="utf-8"))
                if isinstance(data,dict) and isinstance(data.get("profiles"),list): return data
            except (OSError,ValueError): pass
            return {"active":"Default","profiles":[{"name":"Default","avatar":"🙂","theme":"Windows Blue"}]}
        data=load(); active=tk.StringVar(value=data.get("active","Default")); name=tk.StringVar(); avatar=tk.StringVar(value="🙂")
        listing=ttk.Treeview(win,columns=("avatar","name","theme"),show="headings",height=10)
        for col,label,width in [("avatar","Avatar",90),("name","Profile name",300),("theme","Theme",180)]: listing.heading(col,text=label); listing.column(col,width=width)
        listing.pack(fill="both",expand=True,padx=20,pady=8)
        def refresh():
            listing.delete(*listing.get_children())
            for i,p in enumerate(data["profiles"]): listing.insert("","end",iid=str(i),values=(p.get("avatar","🙂"),p.get("name","Profile"),p.get("theme","Default")))
        def persist():
            try:
                path.parent.mkdir(parents=True,exist_ok=True); path.write_text(json.dumps(data,indent=2,ensure_ascii=False),encoding="utf-8")
            except OSError as e: messagebox.showerror("Profiles",str(e),parent=win); return False
            return True
        def add():
            n=name.get().strip()
            if not n: messagebox.showinfo("Profiles","Enter a profile name first.",parent=win); return
            if any(p.get("name","").casefold()==n.casefold() for p in data["profiles"]): messagebox.showinfo("Profiles","That profile already exists.",parent=win); return
            data["profiles"].append({"name":n[:40],"avatar":avatar.get()[:4],"theme":"Windows Blue"}); name.set(""); refresh(); persist()
        def activate():
            sel=listing.selection()
            if not sel:return
            p=data["profiles"][int(sel[0])]; data["active"]=p["name"]
            if persist(): active.set(p["name"]); status.config(text=f"Active profile: {p['name']} (local simulator profile)")
        def delete():
            sel=listing.selection()
            if not sel:return
            p=data["profiles"][int(sel[0])]
            if len(data["profiles"])<2: messagebox.showinfo("Profiles","Keep at least one profile.",parent=win); return
            if not messagebox.askyesno("Delete profile",f"Delete local profile '{p['name']}'?",parent=win):return
            data["profiles"].pop(int(sel[0]))
            if data["active"]==p["name"]: data["active"]=data["profiles"][0]["name"]
            refresh(); persist(); active.set(data["active"])
        form=tk.Frame(win,bg="#f1f5f9");form.pack(fill="x",padx=20,pady=4)
        tk.Entry(form,textvariable=name,font=("Segoe UI",10),width=26).pack(side="left",padx=(0,8))
        ttk.Combobox(form,textvariable=avatar,values=["🙂","😀","🚀","🎮","🌟","🐱","🦊"],width=5,state="readonly").pack(side="left",padx=(0,8))
        tk.Button(form,text="Add profile",command=add,bg=self.accent,fg="white",relief="flat").pack(side="left")
        bar=tk.Frame(win,bg="#f1f5f9");bar.pack(fill="x",padx=20,pady=8)
        tk.Button(bar,text="Set active",command=activate,bg="#dbeafe",relief="flat").pack(side="left")
        tk.Button(bar,text="Delete selected",command=delete,bg="#fee2e2",relief="flat").pack(side="left",padx=8)
