    def nevos_ai_assistant(self):
        """Offline, rule-based helper. No online AI model or network service is used."""
        win=self.window("NevOS AI Assistant", "760x560");win.configure(bg="#f1f5f9")
        tk.Label(win,text="NevOS AI Assistant",font=("Segoe UI",22,"bold"),bg="#f1f5f9",fg="#172238").pack(anchor="w",padx=20,pady=(16,3))
        tk.Label(win,text="Offline helper for NevOS features and shortcuts — no internet AI service is connected.",wraplength=700,bg="#f1f5f9",fg="#526178").pack(anchor="w",padx=20,pady=(0,8))
        chat=tk.Text(win,wrap="word",font=("Segoe UI",10),bg="white",fg="#172238",relief="flat",state="disabled");chat.pack(fill="both",expand=True,padx=20,pady=8)
        entry=tk.Entry(win,font=("Segoe UI",11));entry.pack(fill="x",padx=20,pady=(0,8))
        def reply(q):
            low=q.casefold()
            if any(w in low for w in ("hello","hi","hey")):return "Hello! I can explain NevOS features or open a built-in app for you."
            if "profile" in low:return "Open User Profiles to add, activate, or remove local NevOS profiles. These are not Windows accounts."
            if "update" in low:return "Update Center Pro shows local release notes and can validate a selected Python file. No online update server is configured."
            if "game" in low or "gaming" in low:return "Gaming Mode includes a focus timer. It does not alter Windows performance settings or silence Windows notifications."
            if "desktop" in low or "workspace" in low:return "Open Virtual Desktops to use the existing NevOS workspace simulator."
            if "welcome" in low:return "Welcome Center has shortcuts to important NevOS 15.0 features."
            if "settings" in low:return "Opening Settings gives you access to the existing NevOS configuration panels."
            if "notepad" in low:return "Opening Notepad."
            if "calculator" in low:return "Opening Calculator."
            if "file" in low or "folder" in low:return "Opening File Manager."
            if "help" in low or "what can you do" in low:return "Try asking about profiles, updates, gaming mode, virtual desktops, settings, Notepad, Calculator, or File Manager."
            return "I’m an offline rule-based helper, so I may not understand that yet. Try asking about profiles, updates, gaming mode, virtual desktops, settings, Notepad, Calculator, or File Manager."
        def send():
            q=entry.get().strip()
            if not q:return
            entry.delete(0,"end");answer=reply(q)
            chat.configure(state="normal");chat.insert("end",f"You: {q}\nNevOS Assistant: {answer}\n\n");chat.see("end");chat.configure(state="disabled")
            low=q.casefold()
            if "notepad" in low:self.notepad()
            elif "calculator" in low:self.calculator()
            elif "file manager" in low or "open files" in low:self.files()
            elif "open settings" in low:self.settings()
        bar=tk.Frame(win,bg="#f1f5f9");bar.pack(fill="x",padx=20,pady=(0,14))
        tk.Button(bar,text="Send",command=send,bg=self.accent,fg="white",relief="flat",padx=18,pady=7).pack(side="left")
        tk.Button(bar,text="Clear chat",command=lambda:(chat.configure(state="normal"),chat.delete("1.0","end"),chat.configure(state="disabled")),bg="#dbeafe",relief="flat",padx=12,pady=7).pack(side="left",padx=8)
        entry.bind("<Return>",lambda e:send());chat.configure(state="normal");chat.insert("end","NevOS Assistant: Hi! Ask me about NevOS features. Type ‘help’ to see examples.\n\n");chat.configure(state="disabled")



