    def major_update_hub(self):
        """NevOS 17.0 central hub with working shortcuts, searchable app list, and saved preferences."""
        win = self.window("NevOS 17.0 — Major Update Hub", "900x650")
        win.configure(bg="#eef3f9")
        header = tk.Frame(win, bg="#102b50")
        header.pack(fill="x")
        tk.Label(header, text="NevOS 17.0", font=("Segoe UI", 25, "bold"),
                 bg="#102b50", fg="white").pack(anchor="w", padx=22, pady=(18, 2))
        tk.Label(header, text="Major Update • Desktop • Office • Tools • Personalization • Updates",
                 font=("Segoe UI", 10), bg="#102b50", fg="#c8defb").pack(anchor="w", padx=22, pady=(0, 18))
        body = tk.Frame(win, bg="#eef3f9")
        body.pack(fill="both", expand=True, padx=18, pady=16)

        tk.Label(body, text="Jump back into NevOS", font=("Segoe UI", 16, "bold"),
                 bg="#eef3f9", fg="#14294b").pack(anchor="w", pady=(0, 8))
        search_var = tk.StringVar()
        search = tk.Entry(body, textvariable=search_var, font=("Segoe UI", 11), relief="solid", bd=1)
        search.pack(fill="x", pady=(0, 10), ipady=7)

        app_area = tk.Frame(body, bg="#eef3f9")
        app_area.pack(fill="both", expand=True)
        status = tk.StringVar(value="Choose an app shortcut below.")
        tk.Label(body, textvariable=status, bg="#dbeafe", fg="#1e3a5f",
                 anchor="w", padx=10, pady=8).pack(fill="x", pady=(10, 0))

        shortcuts = [
            ("Office & Documents", "Office", ["Word", "Slides", "Sheets", "Office"]),
            ("Files & Backup", "Files", ["File Explorer", "Backup & Restore", "Recycle Bin"]),
            ("System Tools", "Tools", ["Task Manager", "System Information", "Security", "Quick Settings"]),
            ("Personalization", "Personal", ["Personalization", "Wallpaper", "Theme", "Control Center"]),
            ("Updates", "Updates", ["Update Center", "Update", "Version"]),
            ("Apps & Widgets", "Apps", ["App Store", "Widgets", "Virtual Desktops", "AI Assistant"]),
        ]

        def open_target(name):
            key = name.lower()
            # Bind shortcuts to existing app methods; never execute arbitrary text.
            candidates = [
                (("word", "slides", "sheets", "office"), ("office",)),
                (("file explorer", "files"), ("file_explorer_pro",)),
                (("backup",), ("backup_restore",)),
                (("task manager",), ("task_manager_2", "task_manager_pro")),
                (("system information",), ("system_information", "system_info")),
                (("security",), ("security_settings_center",)),
                (("quick settings", "control center"), ("control_center_pro", "quick_settings")),
                (("personalization", "wallpaper", "theme"), ("personalization_pro", "personalization")),
                (("update center", "update", "version"), ("update_center_2", "update_center_pro")),
                (("app store",), ("app_store_2", "nevos_app_store")),
                (("widgets",), ("super_widgets",)),
                (("virtual desktops",), ("virtual_desktops",)),
                (("ai assistant",), ("nevos_ai_assistant",)),
                (("recycle bin",), ("recycle_bin",)),
            ]
            for terms, attrs in candidates:
                if any(term in key for term in terms):
                    for attr in attrs:
                        fn = getattr(self, attr, None)
                        if callable(fn):
                            try:
                                fn()
                                status.set(f"Opened {name}.")
                            except Exception as exc:
                                messagebox.showerror("Could not open app", str(exc), parent=win)
                            return
            # Fallback to the registered app list, matching visible title/name.
            for app in getattr(self, "apps", []):
                try:
                    if key in str(app[0]).lower() or key in str(app[1]).lower():
                        app[2]()
                        status.set(f"Opened {name}.")
                        return
                except Exception:
                    continue
            status.set(f"No matching built-in app was found for {name}.")

        cards = []
        for title, subtitle, terms in shortcuts:
            card = tk.Frame(app_area, bg="white", highlightbackground="#d4deeb", highlightthickness=1)
            card.pack(fill="x", pady=4)
            tk.Label(card, text=title, font=("Segoe UI", 12, "bold"), bg="white",
                     fg="#14294b").pack(side="left", padx=12, pady=10)
            tk.Label(card, text="  •  ".join(terms), bg="white", fg="#64748b").pack(side="left", padx=8)
            tk.Button(card, text="Open", command=lambda t=title: open_target(t),
                      bg=self.accent, fg="white", relief="flat", padx=12).pack(side="right", padx=10, pady=7)
            cards.append((card, title, subtitle, terms))

        def filter_cards(*_):
            query = search_var.get().strip().lower()
            for card, title, subtitle, terms in cards:
                haystack = " ".join([title, subtitle] + terms).lower()
                card.pack_forget() if query and query not in haystack else card.pack(fill="x", pady=4)
        search_var.trace_add("write", filter_cards)

        footer = tk.Frame(body, bg="#eef3f9")
        footer.pack(fill="x", pady=(10, 0))
        tk.Button(footer, text="Open Update Center", command=lambda: open_target("Update Center"),
                  bg="#dbeafe", fg="#14294b", relief="flat", padx=12, pady=8).pack(side="left")
        tk.Button(footer, text="Open Backup & Restore", command=lambda: open_target("Backup & Restore"),
                  bg="#dbeafe", fg="#14294b", relief="flat", padx=12, pady=8).pack(side="left", padx=8)
        tk.Button(footer, text="Open Personalization", command=lambda: open_target("Personalization"),
                  bg="#dbeafe", fg="#14294b", relief="flat", padx=12, pady=8).pack(side="left")


