    def weather_widget(self):
        """Weather widget using Open-Meteo; user enters a town/city, no API key required."""
        win = self.window("NevOS Weather Widget", "700x590")
        win.configure(bg="#eaf4ff")
        header = tk.Frame(win, bg="#163b68", padx=20, pady=16)
        header.pack(fill="x")
        tk.Label(header, text="🌦  WEATHER", bg="#163b68", fg="white",
                 font=("Segoe UI", 22, "bold")).pack(anchor="w")
        tk.Label(header, text="Current conditions and a 5-day forecast",
                 bg="#163b68", fg="#dbeafe", font=("Segoe UI", 10)).pack(anchor="w", pady=(3, 0))

        search = tk.Frame(win, bg="#eaf4ff", padx=18, pady=14)
        search.pack(fill="x")
        tk.Label(search, text="Town or city", bg="#eaf4ff", fg="#17365d",
                 font=("Segoe UI", 10, "bold")).pack(side="left", padx=(0, 8))
        place_var = tk.StringVar(value="Wadduwa")
        entry = ttk.Entry(search, textvariable=place_var, width=25)
        entry.pack(side="left", padx=(0, 8))
        status = tk.Label(win, text="Enter a place and press Get Weather.",
                          bg="#eaf4ff", fg="#52647a", font=("Segoe UI", 10))
        status.pack(anchor="w", padx=20)

        current = tk.Frame(win, bg="#ffffff", padx=18, pady=15,
                           highlightthickness=1, highlightbackground="#c8d9ec")
        current.pack(fill="x", padx=18, pady=12)
        place_label = tk.Label(current, text="Choose a location", bg="white",
                               fg="#163b68", font=("Segoe UI", 17, "bold"))
        place_label.pack(anchor="w")
        condition_label = tk.Label(current, text="🌤  Weather will appear here",
                                   bg="white", fg="#243b53", font=("Segoe UI", 14))
        condition_label.pack(anchor="w", pady=(8, 3))
        temp_label = tk.Label(current, text="--°C", bg="white", fg="#087eaa",
                              font=("Segoe UI", 30, "bold"))
        temp_label.pack(anchor="w")
        details_label = tk.Label(current, text="Feels like --°C  •  Humidity --%  •  Wind -- km/h",
                                 bg="white", fg="#52647a", font=("Segoe UI", 10))
        details_label.pack(anchor="w", pady=(4, 0))

        forecast_frame = tk.LabelFrame(win, text="5-day forecast", bg="#eaf4ff",
                                       fg="#163b68", padx=10, pady=8,
                                       font=("Segoe UI", 10, "bold"))
        forecast_frame.pack(fill="both", expand=True, padx=18, pady=(0, 12))
        forecast_text = tk.Text(forecast_frame, height=8, wrap="word",
                                font=("Segoe UI", 10), bg="white", fg="#243b53",
                                relief="flat", padx=10, pady=8)
        forecast_text.pack(fill="both", expand=True)
        forecast_text.insert("1.0", "Your forecast will appear here.")
        forecast_text.configure(state="disabled")

        code_map = {
            0: "Clear sky", 1: "Mainly clear", 2: "Partly cloudy", 3: "Overcast",
            45: "Fog", 48: "Depositing rime fog", 51: "Light drizzle",
            53: "Drizzle", 55: "Heavy drizzle", 56: "Freezing drizzle",
            57: "Dense freezing drizzle", 61: "Light rain", 63: "Rain",
            65: "Heavy rain", 66: "Freezing rain", 67: "Heavy freezing rain",
            71: "Light snow", 73: "Snow", 75: "Heavy snow", 77: "Snow grains",
            80: "Rain showers", 81: "Moderate rain showers", 82: "Violent rain showers",
            85: "Snow showers", 86: "Heavy snow showers", 95: "Thunderstorm",
            96: "Thunderstorm with hail", 99: "Severe thunderstorm with hail"
        }

        def fetch_weather():
            city = place_var.get().strip()
            if not city:
                status.configure(text="Please enter a town or city.", fg="#b42318")
                return
            status.configure(text="Loading weather…", fg="#52647a")
            button.configure(state="disabled")
            def worker():
                try:
                    import urllib.parse
                    q = urllib.parse.urlencode({"name": city, "count": 1, "language": "en", "format": "json"})
                    req = urllib.request.Request("https://geocoding-api.open-meteo.com/v1/search?" + q,
                                                 headers={"User-Agent": "NevOS-Weather/1.0"})
                    with urllib.request.urlopen(req, timeout=10) as response:
                        geo = json.loads(response.read().decode("utf-8"))
                    results = geo.get("results") or []
                    if not results:
                        raise ValueError("Location not found. Try a nearby town or city.")
                    loc = results[0]
                    params = urllib.parse.urlencode({
                        "latitude": loc["latitude"], "longitude": loc["longitude"],
                        "current": "temperature_2m,relative_humidity_2m,apparent_temperature,weather_code,wind_speed_10m",
                        "daily": "weather_code,temperature_2m_max,temperature_2m_min",
                        "forecast_days": 5, "timezone": "auto"
                    })
                    req = urllib.request.Request("https://api.open-meteo.com/v1/forecast?" + params,
                                                 headers={"User-Agent": "NevOS-Weather/1.0"})
                    with urllib.request.urlopen(req, timeout=10) as response:
                        data = json.loads(response.read().decode("utf-8"))
                    cur, daily = data["current"], data["daily"]
                    desc = code_map.get(cur.get("weather_code"), "Conditions unavailable")
                    lines = []
                    for i, day in enumerate(daily.get("time", [])):
                        day_desc = code_map.get(daily["weather_code"][i], "Conditions unavailable")
                        lines.append(f'{day}   •   {day_desc}   •   High {daily["temperature_2m_max"][i]}°C / Low {daily["temperature_2m_min"][i]}°C')
                    display_place = ", ".join(x for x in [loc.get("name"), loc.get("admin1"), loc.get("country")] if x)
                    def show():
                        if not win.winfo_exists(): return
                        place_label.configure(text=display_place)
                        condition_label.configure(text=f"🌦  {desc}")
                        temp_label.configure(text=f'{cur["temperature_2m"]}°C')
                        details_label.configure(text=f'Feels like {cur["apparent_temperature"]}°C  •  Humidity {cur["relative_humidity_2m"]}%  •  Wind {cur["wind_speed_10m"]} km/h')
                        forecast_text.configure(state="normal")
                        forecast_text.delete("1.0", "end")
                        forecast_text.insert("1.0", "\n".join(lines))
                        forecast_text.configure(state="disabled")
                        status.configure(text="Weather updated just now. Internet connection required.", fg="#18794e")
                        button.configure(state="normal")
                    win.after(0, show)
                except Exception as exc:
                    def show_error():
                        if not win.winfo_exists(): return
                        status.configure(text=f"Could not load weather: {exc}", fg="#b42318")
                        button.configure(state="normal")
                    win.after(0, show_error)
            threading.Thread(target=worker, daemon=True).start()

        button = tk.Button(search, text="Get Weather", command=fetch_weather,
                           bg="#087eaa", fg="white", activebackground="#086b91",
                           activeforeground="white", relief="flat", padx=12, pady=5,
                           cursor="hand2")
        button.pack(side="left")
        tk.Label(win, text="Weather data by Open-Meteo • Requires internet • No API key",
                 bg="#eaf4ff", fg="#52647a", font=("Segoe UI", 8)).pack(anchor="w", padx=20, pady=(0, 10))
        entry.bind("<Return>", lambda _event: fetch_weather())
        fetch_weather()

    def widgets_center(self):
        """Local clock, calendar, and notes widgets without external services."""
        win = self.window("NevOS 18.0 — Widgets Center", "650x560")
        win.configure(bg="#f2f6fc")
        tk.Label(win, text="Widgets Center", font=("Segoe UI", 24, "bold"),
                 bg="#f2f6fc", fg="#142b4a").pack(anchor="w", padx=20, pady=(18, 8))
        grid = tk.Frame(win, bg="#f2f6fc")
        grid.pack(fill="both", expand=True, padx=16, pady=8)
        clock = tk.Frame(grid, bg="#dbeafe", padx=16, pady=14)
        clock.pack(fill="x", pady=6)
        tk.Label(clock, text="LOCAL TIME", bg="#dbeafe", fg="#1e40af",
                 font=("Segoe UI", 9, "bold")).pack(anchor="w")
        time_label = tk.Label(clock, text="", bg="#dbeafe", fg="#172554",
                              font=("Segoe UI", 25, "bold"))
        time_label.pack(anchor="w")
        date_label = tk.Label(clock, text="", bg="#dbeafe", fg="#1e40af", font=("Segoe UI", 10))
        date_label.pack(anchor="w")
        def tick():
            if not win.winfo_exists(): return
            now = datetime.now()
            time_label.configure(text=now.strftime("%I:%M:%S %p"))
            date_label.configure(text=now.strftime("%A, %d %B %Y"))
            win.after(1000, tick)
        tick()
        cal_frame = tk.LabelFrame(grid, text="Calendar", bg="#ffffff", padx=12, pady=8)
        cal_frame.pack(fill="x", pady=6)
        now = datetime.now()
        tk.Label(cal_frame, text=calendar.month(now.year, now.month), justify="left",
                 font=("Consolas", 11), bg="white", fg="#1f2937").pack(anchor="w")
        note_frame = tk.LabelFrame(grid, text="Quick notes (saved locally)", bg="#ffffff", padx=10, pady=8)
        note_frame.pack(fill="both", expand=True, pady=6)
        notes_path = Path.home() / ".nevos7" / "widget_notes.txt"
        notes_path.parent.mkdir(parents=True, exist_ok=True)
        note = tk.Text(note_frame, height=5, wrap="word", font=("Segoe UI", 10))
        note.pack(fill="both", expand=True)
        try: note.insert("1.0", notes_path.read_text(encoding="utf-8"))
        except Exception: pass
        def save_notes():
            try:
                notes_path.write_text(note.get("1.0", "end-1c"), encoding="utf-8")
                messagebox.showinfo("Widgets Center", "Notes saved.", parent=win)
            except Exception as exc:
                messagebox.showerror("Widgets Center", str(exc), parent=win)
        tk.Button(note_frame, text="Save notes", command=save_notes).pack(anchor="e", pady=(6, 0))

    def nevos_app_store(self):
        """Simple catalog of apps already bundled with NevOS; not a package downloader."""
        win = self.window("NevOS App Store", "720x570")
        win.configure(bg="#f3f6fb")
        tk.Label(win, text="NevOS App Store", font=("Segoe UI", 24, "bold"),
                 bg="#f3f6fb", fg="#172b4a").pack(anchor="w", padx=20, pady=(18, 4))
        tk.Label(win, text="Launch built-in apps from one searchable catalog.",
                 bg="#f3f6fb", fg="#52647c").pack(anchor="w", padx=22)
        search = tk.StringVar()
        ent = tk.Entry(win, textvariable=search, font=("Segoe UI", 11))
        ent.pack(fill="x", padx=20, pady=12)
        listing = tk.Listbox(win, font=("Segoe UI", 11), height=17, activestyle="dotbox")
        listing.pack(fill="both", expand=True, padx=20, pady=(0, 8))
        actions = tk.Frame(win, bg="#f3f6fb")
        actions.pack(fill="x", padx=20, pady=(0, 16))
        app_rows = [(str(row[1]), row[2]) for row in getattr(self, "apps", []) if len(row) >= 3]
        visible = []
        def refresh(*_):
            listing.delete(0, "end")
            visible.clear()
            q = search.get().casefold().strip()
            for name, func in app_rows:
                if q in name.casefold():
                    visible.append((name, func))
                    listing.insert("end", name)
        def launch(_=None):
            sel = listing.curselection()
            if not sel: return
            name, func = visible[sel[0]]
            try: func()
            except Exception as exc: messagebox.showerror("App Store", f"Could not open {name}:\n{exc}", parent=win)
        search.trace_add("write", refresh)
        listing.bind("<Double-Button-1>", launch)
        tk.Button(actions, text="Open selected app", command=launch).pack(side="left")
        tk.Label(actions, text="This catalog does not download third-party apps.",
                 bg="#f3f6fb", fg="#6b7280").pack(side="right")
        refresh()

    def more_games(self):
        """Adds three self-contained mini-games."""
        win = self.window("NevOS Games Arcade", "700x560")
        win.configure(bg="#101827")
        tk.Label(win, text="NevOS Games Arcade", font=("Segoe UI", 23, "bold"),
                 bg="#101827", fg="#f8fafc").pack(anchor="w", padx=20, pady=(18, 8))
        tabs = ttk.Notebook(win)
        tabs.pack(fill="both", expand=True, padx=16, pady=12)
        # Number Guess
        g1 = tk.Frame(tabs, bg="#f8fafc"); tabs.add(g1, text="Number Guess")
        secret = random.randint(1, 100)
        tk.Label(g1, text="Guess the hidden number (1–100).", bg="#f8fafc",
                 font=("Segoe UI", 12)).pack(pady=16)
        guess_var = tk.StringVar()
        tk.Entry(g1, textvariable=guess_var, width=12, font=("Segoe UI", 16)).pack()
        g1msg = tk.Label(g1, text="You have unlimited tries.", bg="#f8fafc")
        g1msg.pack(pady=10)
        def check_guess():
            try: n = int(guess_var.get())
            except ValueError:
                g1msg.configure(text="Enter a whole number.")
                return
            if not 1 <= n <= 100:
                g1msg.configure(text="Choose a number from 1 to 100.")
            elif n == secret:
                g1msg.configure(text="Correct! You found it. Start a new round to play again.")
            elif n < secret: g1msg.configure(text="Too low — try again!")
            else: g1msg.configure(text="Too high — try again!")
        tk.Button(g1, text="Guess", command=check_guess).pack()
        def new_round():
            nonlocal secret
            secret = random.randint(1, 100)
            g1msg.configure(text="New number chosen!")
            guess_var.set("")
        tk.Button(g1, text="New round", command=new_round).pack(pady=8)
        # Rock paper scissors
        g2 = tk.Frame(tabs, bg="#f8fafc"); tabs.add(g2, text="Rock Paper Scissors")
        tk.Label(g2, text="Choose your move", bg="#f8fafc", font=("Segoe UI", 12)).pack(pady=16)
        rps_msg = tk.Label(g2, text="Ready?", bg="#f8fafc")
        rps_msg.pack(pady=8)
        def play_rps(move):
            bot = random.choice(["Rock", "Paper", "Scissors"])
            if move == bot: result = "It's a tie!"
            elif (move, bot) in [("Rock","Scissors"),("Paper","Rock"),("Scissors","Paper")]: result = "You win!"
            else: result = "Computer wins!"
            rps_msg.configure(text=f"You: {move} | Computer: {bot} — {result}")
        for move in ("Rock", "Paper", "Scissors"):
            tk.Button(g2, text=move, command=lambda m=move: play_rps(m)).pack(side="left", padx=22, pady=12)
        # Click counter
        g3 = tk.Frame(tabs, bg="#f8fafc"); tabs.add(g3, text="Click Challenge")
        clicks = {"count": 0, "active": False}
        click_msg = tk.Label(g3, text="Press Start, then click as fast as you can for 10 seconds.",
                             bg="#f8fafc", font=("Segoe UI", 11))
        click_msg.pack(pady=20)
        click_button = tk.Button(g3, text="Start", command=lambda: start_clicks())
        click_button.pack(pady=12)
        def start_clicks():
            clicks.update(count=0, active=True)
            click_button.configure(text="Click!", command=hit_click)
            click_msg.configure(text="Go! 10 seconds...")
            win.after(10000, finish_clicks)
        def hit_click():
            if clicks["active"]:
                clicks["count"] += 1
                click_msg.configure(text=f"Clicks: {clicks['count']}")
        def finish_clicks():
            clicks["active"] = False
            click_button.configure(text="Start", command=start_clicks)
            click_msg.configure(text=f"Time! Final score: {clicks['count']} clicks.")

