    def backup_restore(self):
        """Back up and restore NevOS user data as a ZIP, without touching Windows files."""
        win = self.window("NevOS Backup & Restore", "720x500")
        win.configure(bg="#f1f5f9")
        tk.Label(win, text="Backup & Restore", font=("Segoe UI", 22, "bold"),
                 bg="#f1f5f9", fg="#172238").pack(anchor="w", padx=20, pady=(18, 4))
        tk.Label(win, text="Back up NevOS settings and data from your .nevos7 folder. Restore extracts only into that folder.",
                 wraplength=660, justify="left", bg="#f1f5f9", fg="#526178").pack(anchor="w", padx=20, pady=(0, 14))
        data_dir = self._data_dir()
        tk.Label(win, text=f"Data folder: {data_dir}", wraplength=660, bg="#f1f5f9", fg="#334155").pack(anchor="w", padx=20, pady=4)
        status = tk.Label(win, text="Choose an action below.", bg="#f1f5f9", fg="#334155", wraplength=650)
        status.pack(anchor="w", padx=20, pady=12)
        def make_backup():
            target = filedialog.asksaveasfilename(parent=win, title="Save NevOS backup", defaultextension=".zip", filetypes=[("ZIP backup", "*.zip")], initialfile=f"NevOS_Backup_{datetime.now():%Y%m%d_%H%M%S}.zip")
            if not target: return
            try:
                with zipfile.ZipFile(target, "w", zipfile.ZIP_DEFLATED) as zf:
                    if data_dir.exists():
                        for path in data_dir.rglob("*"):
                            if path.is_file(): zf.write(path, Path("nevos7") / path.relative_to(data_dir))
                    zf.writestr("backup_metadata.json", json.dumps({"version": NEVOS_VERSION, "created": datetime.now().isoformat(timespec="seconds")}, indent=2))
                status.config(text=f"Backup created: {target}")
                messagebox.showinfo("Backup complete", "NevOS data backup created successfully.", parent=win)
            except Exception as exc:
                messagebox.showerror("Backup failed", str(exc), parent=win)
        def restore_backup():
            source = filedialog.askopenfilename(parent=win, title="Choose NevOS backup", filetypes=[("ZIP backup", "*.zip")])
            if not source: return
            if not messagebox.askyesno("Restore backup", "Restore files into NevOS's data folder? Existing files with matching names may be replaced.", parent=win): return
            try:
                root = data_dir.resolve()
                with zipfile.ZipFile(source, "r") as zf:
                    members = []
                    for info in zf.infolist():
                        if info.is_dir() or info.filename == "backup_metadata.json": continue
                        p = Path(info.filename)
                        if p.is_absolute() or ".." in p.parts or not p.parts or p.parts[0] != "nevos7":
                            raise ValueError("Backup contains an unsafe or unexpected path.")
                        rel = Path(*p.parts[1:])
                        dest = (root / rel).resolve()
                        if dest != root and root not in dest.parents:
                            raise ValueError("Backup contains a path outside the NevOS data folder.")
                        members.append((info, dest))
                    for info, dest in members:
                        dest.parent.mkdir(parents=True, exist_ok=True)
                        with zf.open(info) as inp, open(dest, "wb") as out_file: shutil.copyfileobj(inp, out_file)
                status.config(text=f"Restored {len(members)} file(s) into {data_dir}")
                messagebox.showinfo("Restore complete", f"Restored {len(members)} file(s).", parent=win)
            except Exception as exc:
                messagebox.showerror("Restore failed", str(exc), parent=win)
        bar = tk.Frame(win, bg="#f1f5f9"); bar.pack(anchor="w", padx=20, pady=10)
        tk.Button(bar, text="Create Backup", command=make_backup, bg=self.accent, fg="white", relief="flat", padx=16, pady=9).pack(side="left")
        tk.Button(bar, text="Restore Backup", command=restore_backup, bg="#dbeafe", fg="#172238", relief="flat", padx=16, pady=9).pack(side="left", padx=10)
        tk.Button(bar, text="Open Data Folder", command=lambda: webbrowser.open(data_dir.as_uri()), bg="#e2e8f0", fg="#172238", relief="flat", padx=16, pady=9).pack(side="left")



