    def mini_games_arcade_19(self):
        """Small self-contained games with no network or extra packages."""
        win = self.window("NevOS 19.0 — Mini-Games Arcade", "620x500")
        win.configure(bg="#f2f6fc")
        tk.Label(win, text="Mini-Games Arcade", font=("Segoe UI", 23, "bold"),
                 bg="#f2f6fc", fg="#18345b").pack(anchor="w", padx=20, pady=(18, 4))
        tabs = ttk.Notebook(win); tabs.pack(fill="both", expand=True, padx=16, pady=12)
        guess = tk.Frame(tabs, bg="white"); tabs.add(guess, text="Number Guess")
        tk.Label(guess, text="Guess a number from 1 to 50", font=("Segoe UI", 14, "bold"), bg="white").pack(pady=(24, 8))
        secret = random.randint(1, 50); attempts = [0]
        entry = tk.Entry(guess, font=("Segoe UI", 13), justify="center"); entry.pack(pady=6)
        status = tk.Label(guess, text="Enter a number and press Guess.", bg="white", fg="#42536a"); status.pack(pady=8)
        def check():
            try: n = int(entry.get())
            except ValueError:
                status.config(text="Please enter a whole number from 1 to 50."); return
            if not 1 <= n <= 50:
                status.config(text="Choose a number between 1 and 50."); return
            attempts[0] += 1
            if n == secret:
                status.config(text=f"Correct! You won in {attempts[0]} guesses.")
            elif n < secret: status.config(text="Too low — try a bigger number.")
            else: status.config(text="Too high — try a smaller number.")
        tk.Button(guess, text="Guess", command=check, bg=self.accent, fg="white", relief="flat", padx=20, pady=6).pack()
        def reset():
            nonlocal_secret[0] = random.randint(1, 50); attempts[0] = 0; status.config(text="New game! Enter a number."); entry.delete(0, "end")
        nonlocal_secret = [secret]
        # Use a mutable target so New Game can reset without recreating the tab.
        secret_box = nonlocal_secret
        def check():
            try: n = int(entry.get())
            except ValueError:
                status.config(text="Please enter a whole number from 1 to 50."); return
            if not 1 <= n <= 50:
                status.config(text="Choose a number between 1 and 50."); return
            attempts[0] += 1
            if n == secret_box[0]: status.config(text=f"Correct! You won in {attempts[0]} guesses.")
            elif n < secret_box[0]: status.config(text="Too low — try a bigger number.")
            else: status.config(text="Too high — try a smaller number.")
        # Rebind the button to the reset-safe checker.
        for child in guess.winfo_children():
            if isinstance(child, tk.Button) and child.cget("text") == "Guess": child.config(command=check)
        tk.Button(guess, text="New Game", command=reset, bg="#dbeafe", fg="#17345c", relief="flat", padx=16, pady=6).pack(pady=8)

        rps = tk.Frame(tabs, bg="white"); tabs.add(rps, text="Rock Paper Scissors")
        tk.Label(rps, text="Choose your move", font=("Segoe UI", 14, "bold"), bg="white").pack(pady=(30, 12))
        result = tk.Label(rps, text="Ready when you are!", font=("Segoe UI", 11), bg="white", fg="#42536a"); result.pack(pady=12)
        def play(move):
            cpu = random.choice(["Rock", "Paper", "Scissors"])
            if move == cpu: outcome = "It's a tie!"
            elif (move, cpu) in [("Rock","Scissors"),("Paper","Rock"),("Scissors","Paper")]: outcome = "You win!"
            else: outcome = "Computer wins!"
            result.config(text=f"You: {move}  |  Computer: {cpu}\\n{outcome}")
        buttons = tk.Frame(rps, bg="white"); buttons.pack(pady=12)
        for move in ["Rock", "Paper", "Scissors"]:
            tk.Button(buttons, text=move, command=lambda m=move: play(m), bg=self.accent, fg="white", relief="flat", padx=12, pady=8).pack(side="left", padx=5)

        clicker = tk.Frame(tabs, bg="white"); tabs.add(clicker, text="Click Challenge")
        score = [0]; tk.Label(clicker, text="Click as many times as you can!", font=("Segoe UI", 14, "bold"), bg="white").pack(pady=(30, 12))
        score_label = tk.Label(clicker, text="Score: 0", font=("Segoe UI", 16, "bold"), bg="white"); score_label.pack(pady=8)
        tk.Button(clicker, text="CLICK!", command=lambda: (score.__setitem__(0, score[0]+1), score_label.config(text=f"Score: {score[0]}")),
                  bg=self.accent, fg="white", relief="flat", font=("Segoe UI", 14, "bold"), padx=25, pady=14).pack(pady=12)
        tk.Label(clicker, text="Score resets when this window closes.", bg="white", fg="#64748b").pack()


    def super_file_explorer_21(self):
        """A safer, modern-style file browser for the user's home folder."""
        import os, shutil
        win=tk.Toplevel(self.root); win.title("Super File Explorer · NevOS 21.0"); win.geometry("900x590"); win.configure(bg="#f3f6fb")
        current=[Path.home()]
        tk.Label(win,text="📁  File Explorer",font=("Segoe UI",20,"bold"),bg="#f3f6fb",fg="#172238").pack(anchor="w",padx=18,pady=(14,2))
        tk.Label(win,text="Browse real files on this computer · delete actions require confirmation",font=("Segoe UI",9),bg="#f3f6fb",fg="#64748b").pack(anchor="w",padx=20)
        bar=tk.Frame(win,bg="#f3f6fb"); bar.pack(fill="x",padx=16,pady=10)
        location=tk.StringVar(value=str(current[0])); entry=tk.Entry(bar,textvariable=location,font=("Segoe UI",10),relief="flat"); entry.pack(side="left",fill="x",expand=True,ipady=7,padx=(0,8))
        body=tk.Frame(win,bg="white",highlightbackground="#d9e2ef",highlightthickness=1); body.pack(fill="both",expand=True,padx=16,pady=(0,14))
        cols=("kind","size"); tree=ttk.Treeview(body,columns=cols,show="tree headings"); tree.heading("#0",text="Name"); tree.heading("kind",text="Type"); tree.heading("size",text="Size"); tree.column("#0",width=480); tree.column("kind",width=140); tree.column("size",width=120,anchor="e"); tree.pack(fill="both",expand=True,padx=8,pady=8)
        def load(path=None):
            p=Path(path or location.get()).expanduser()
            try:
                p=p.resolve(); items=sorted(p.iterdir(),key=lambda x:(not x.is_dir(),x.name.lower()))
            except Exception as e: messagebox.showerror("File Explorer",f"Cannot open this folder:\n{e}",parent=win); return
            current[0]=p; location.set(str(p)); tree.delete(*tree.get_children())
            for item in items:
                try: kind="Folder" if item.is_dir() else (item.suffix or "File"); size="—" if item.is_dir() else f"{item.stat().st_size:,} B"
                except OSError: kind="Unavailable"; size="—"
                tree.insert("","end",text=item.name,values=(kind,size))
        def selected_path():
            sel=tree.selection()
            return current[0]/tree.item(sel[0],"text") if sel else None
        def open_selected(_=None):
            p=selected_path()
            if p and p.is_dir(): load(p)
            elif p:
                try: os.startfile(str(p))
                except Exception: messagebox.showinfo("Selected file",str(p),parent=win)
        def new_folder():
            name=simpledialog.askstring("New folder","Folder name:",parent=win)
            if name and name.strip() and Path(name).name==name and name not in (".",".."):
                try: (current[0]/name).mkdir(); load()
                except Exception as e: messagebox.showerror("New folder",str(e),parent=win)
        def new_text():
            name=simpledialog.askstring("New text file","File name (for example notes.txt):",parent=win)
            if name and name.strip() and Path(name).name==name:
                try: (current[0]/name).open("x",encoding="utf-8").write(""); load()
                except Exception as e: messagebox.showerror("New file",str(e),parent=win)
        def delete_item():
            p=selected_path()
            if not p: return
            if not messagebox.askyesno("Confirm delete",f"Move this item to deletion?\n\n{p}\n\nThis cannot be undone by NevOS.",parent=win): return
            try:
                if p.is_dir(): shutil.rmtree(p)
                else: p.unlink()
                load()
            except Exception as e: messagebox.showerror("Delete failed",str(e),parent=win)
        for label,cmd in [("Go",lambda:load()),("Home",lambda:load(Path.home())),("Up",lambda:load(current[0].parent)),("New folder",new_folder),("New text file",new_text),("Delete selected",delete_item)]:
            tk.Button(bar,text=label,command=cmd,bg="#e3edfb",fg="#17345c",relief="flat",padx=9,pady=6).pack(side="left",padx=2)
        tree.bind("<Double-1>",open_selected); entry.bind("<Return>",lambda e:load()); load()

