        catalog=[("Super File Explorer 21","Productivity",self.super_file_explorer_21),("Widgets Center 21","Tools",self.widgets_center_21),("Task Manager 21","System tools",self.task_manager_21),("Advanced Desktop 21","Desktop",self.advanced_desktop_21),("Gaming Center 21","Games",self.gaming_center_21),("Office Suite 19.0","Productivity",self.office_suite_19),("Settings","System",self.settings),("Calculator","Tools",self.calculator)]
        ids={}
