        def launch(_=None):
            sel=listing.selection()
            if sel: ids[sel[0]]()
        search.trace_add("write",refresh); listing.bind("<Double-1>",launch); tk.Button(win,text="Open selected app",command=launch,bg=self.accent,fg="white",relief="flat",padx=14,pady=8).pack(anchor="e",padx=20,pady=12); refresh()
        tk.Label(win,text="This catalogue launches built-in NevOS apps; it does not download third-party software.",bg="#f3f6fb",fg="#64748b").pack(anchor="w",padx=20,pady=(0,12))

