    def gaming_center_21(self):
        import random
        win=tk.Toplevel(self.root); win.title("Gaming Center · NevOS 21.0"); win.geometry("680x500"); win.configure(bg="#f3f6fb")
        tk.Label(win,text="Gaming Center",font=("Segoe UI",22,"bold"),bg="#f3f6fb",fg="#172238").pack(anchor="w",padx=20,pady=14)
        tabs=ttk.Notebook(win); tabs.pack(fill="both",expand=True,padx=16,pady=(0,16))
        f=tk.Frame(tabs,bg="white"); tabs.add(f,text="Number Guess")
        secret=[random.randint(1,100)]; attempts=[0]
        tk.Label(f,text="Guess a number from 1 to 100",font=("Segoe UI",14,"bold"),bg="white").pack(pady=20)
        ent=tk.Entry(f,font=("Segoe UI",12),justify="center"); ent.pack(pady=5)
        out=tk.Label(f,text="Enter a number and press Guess.",bg="white",fg="#475569"); out.pack(pady=10)
        def guess():
            try: n=int(ent.get()); assert 1<=n<=100
            except Exception: out.config(text="Enter a whole number from 1 to 100."); return
            attempts[0]+=1
            out.config(text=("Correct! Attempts: %d"%attempts[0]) if n==secret[0] else ("Too low!" if n<secret[0] else "Too high!"))
        def reset(): secret[0]=random.randint(1,100); attempts[0]=0; ent.delete(0,"end"); out.config(text="New number chosen. Good luck!")
        tk.Button(f,text="Guess",command=guess,bg=self.accent,fg="white",relief="flat",padx=18,pady=7).pack(pady=4); tk.Button(f,text="New Game",command=reset,bg="#dbeafe",fg="#17345c",relief="flat",padx=14,pady=6).pack(pady=4)
        g=tk.Frame(tabs,bg="white"); tabs.add(g,text="Rock Paper Scissors")
        result=tk.Label(g,text="Pick your move!",font=("Segoe UI",13),bg="white"); result.pack(pady=30)
        def play(m):
            c=random.choice(["Rock","Paper","Scissors"]); result.config(text=f"You: {m}  •  Computer: {c}\n"+("Tie!" if m==c else "You win!" if (m,c) in [("Rock","Scissors"),("Paper","Rock"),("Scissors","Paper")] else "Computer wins!"))
        row=tk.Frame(g,bg="white"); row.pack()
        for m in ["Rock","Paper","Scissors"]: tk.Button(row,text=m,command=lambda x=m:play(x),bg="#dbeafe",relief="flat",padx=12,pady=8).pack(side="left",padx=5)
        cframe=tk.Frame(tabs,bg="white"); tabs.add(cframe,text="Click Challenge"); score=[0]
        lab=tk.Label(cframe,text="Score: 0",font=("Segoe UI",18,"bold"),bg="white"); lab.pack(pady=25)
        tk.Button(cframe,text="CLICK!",command=lambda:(score.__setitem__(0,score[0]+1),lab.config(text=f"Score: {score[0]}")),font=("Segoe UI",16,"bold"),bg=self.accent,fg="white",relief="flat",padx=25,pady=16).pack()
        tk.Label(cframe,text="Scores reset when this window closes.",bg="white",fg="#64748b").pack(pady=12)



    def ultimate_system_dashboard_22(self):
        """Live, read-only system dashboard for the NevOS simulator."""
        import platform, time
        win=self.window("NevOS 22.0 — System Dashboard", "760x560")
        win.configure(bg="#f3f6fb")
        tk.Label(win,text="System Dashboard",font=("Segoe UI",22,"bold"),bg="#f3f6fb",fg="#172238").pack(anchor="w",padx=22,pady=(18,4))
        tk.Label(win,text="Read-only information about this Python session and computer.",bg="#f3f6fb",fg="#64748b").pack(anchor="w",padx=23)
        panel=tk.Frame(win,bg="white",highlightbackground="#dbe3ef",highlightthickness=1); panel.pack(fill="both",expand=True,padx=20,pady=16)
        info=tk.Text(panel,wrap="word",font=("Consolas",11),relief="flat",bg="white",fg="#172238",padx=14,pady=14); info.pack(fill="both",expand=True)
        def refresh():
            try:
                import psutil
                cpu=f"{psutil.cpu_percent(interval=None):.1f}%"; mem=psutil.virtual_memory(); memory=f"{mem.percent:.1f}% used ({mem.used//(1024**2):,} / {mem.total//(1024**2):,} MiB)"; disk=psutil.disk_usage(str(Path.home())); disktext=f"{disk.percent:.1f}% used ({disk.free//(1024**3):,} GiB free)"; extra="psutil available"
            except Exception:
                cpu="Not available (optional psutil package not installed)"; memory="Not available"; disktext="Not available"; extra="Using Python standard library only"
            info.delete("1.0","end"); info.insert("end",f"NevOS version: {NEVOS_VERSION}\nPython: {sys.version.split()[0]}\nOperating system: {platform.platform()}\nMachine: {platform.machine()}\nProcessor: {platform.processor() or 'Not reported'}\nHome folder: {Path.home()}\nCPU usage: {cpu}\nMemory: {memory}\nHome drive: {disktext}\n\n{extra}\n\nThis dashboard does not manage or terminate Windows processes.")
        tk.Button(win,text="Refresh information",command=refresh,bg=self.accent,fg="white",relief="flat",padx=14,pady=8).pack(anchor="w",padx=20,pady=(0,16)); refresh()

    def notes_knowledge_base_22(self):
        """Autosaving notes stored in the user's NevOS data folder."""
        data=self._data_dir()/"notes22"; data.mkdir(parents=True,exist_ok=True)
        win=self.window("NevOS 22.0 — Notes", "800x600"); win.configure(bg="#f3f6fb")
        tk.Label(win,text="Notes & Knowledge Base",font=("Segoe UI",21,"bold"),bg="#f3f6fb",fg="#172238").pack(anchor="w",padx=18,pady=(14,6))
        bar=tk.Frame(win,bg="#f3f6fb"); bar.pack(fill="x",padx=18)
        files=ttk.Combobox(bar,state="readonly",width=32); files.pack(side="left",padx=(0,8))
        name=tk.StringVar(value="My note.txt"); tk.Entry(bar,textvariable=name,width=28).pack(side="left",padx=4)
        status=tk.Label(win,text=f"Saved in {data}",bg="#f3f6fb",fg="#64748b"); status.pack(anchor="w",padx=20,pady=5)
        text=tk.Text(win,wrap="word",font=("Segoe UI",11),undo=True,relief="flat",bg="white",fg="#172238"); text.pack(fill="both",expand=True,padx=18,pady=8)
        current=[None]; pending=[None]
        def refresh():
            names=sorted(p.name for p in data.glob("*.txt")); files["values"]=names
            if names and not files.get(): files.set(names[0])
        def save(show=True):
            n=Path(name.get().strip()).name
            if not n: messagebox.showwarning("Notes","Enter a note filename.",parent=win); return
            if not n.lower().endswith('.txt'): n += '.txt'
            try:
                target=data/n; target.write_text(text.get("1.0","end-1c"),encoding="utf-8"); current[0]=target; name.set(n); refresh(); files.set(n); status.config(text=f"Saved: {target}")
                if show: messagebox.showinfo("Notes","Note saved.",parent=win)
            except OSError as e: messagebox.showerror("Notes",str(e),parent=win)
        def load(_=None):
            n=files.get()
            if not n:return
            target=data/n
            try: content=target.read_text(encoding="utf-8")
            except OSError as e: messagebox.showerror("Notes",str(e),parent=win); return
            text.delete("1.0","end"); text.insert("1.0",content); name.set(n); current[0]=target; status.config(text=f"Opened: {target}")
        def new():
            if text.get("1.0","end-1c").strip() and not messagebox.askyesno("New note","Start a new note? Save the current note first if needed.",parent=win): return
            text.delete("1.0","end"); name.set("New note.txt"); files.set(""); current[0]=None
        files.bind("<<ComboboxSelected>>",load)
        tk.Button(bar,text="New",command=new).pack(side="left",padx=4); tk.Button(bar,text="Save",command=save,bg=self.accent,fg="white",relief="flat").pack(side="left",padx=4)
        refresh()

    def archive_manager_22(self):
        """Create and safely inspect ZIP archives using Python's standard library."""
        win=self.window("NevOS 22.0 — Archive Manager", "700x450"); win.configure(bg="#f3f6fb")
        tk.Label(win,text="Archive Manager",font=("Segoe UI",22,"bold"),bg="#f3f6fb",fg="#172238").pack(anchor="w",padx=20,pady=(18,5))
        tk.Label(win,text="Create ZIP files or inspect archive contents. Extraction asks for a destination.",bg="#f3f6fb",fg="#64748b").pack(anchor="w",padx=21)
        status=tk.Label(win,text="Choose an action below.",bg="#f3f6fb",fg="#334155",wraplength=620,justify="left"); status.pack(anchor="w",padx=22,pady=18)
        def create_zip():
            files=filedialog.askopenfilenames(parent=win,title="Choose files to add to ZIP")
            if not files:return
            dest=filedialog.asksaveasfilename(parent=win,title="Save ZIP archive",defaultextension=".zip",filetypes=[("ZIP archive","*.zip")])
            if not dest:return
            try:
                with zipfile.ZipFile(dest,"w",zipfile.ZIP_DEFLATED) as z:
                    for f in files:z.write(f,arcname=Path(f).name)
                status.config(text=f"Created {dest}\nFiles added: {len(files)}")
            except Exception as e:messagebox.showerror("Archive Manager",str(e),parent=win)
        def inspect():
            source=filedialog.askopenfilename(parent=win,title="Choose ZIP archive",filetypes=[("ZIP archive","*.zip")])
            if not source:return
            try:
                with zipfile.ZipFile(source) as z:
                    entries=z.infolist(); summary="\n".join(f"{i.filename}  ({i.file_size:,} bytes)" for i in entries[:100])
                status.config(text=f"{Path(source).name}: {len(entries)} entries\n\n{summary or '(empty archive)'}")
            except Exception as e:messagebox.showerror("Archive Manager",str(e),parent=win)
        def extract():
            source=filedialog.askopenfilename(parent=win,title="Choose ZIP archive",filetypes=[("ZIP archive","*.zip")])
            if not source:return
            dest=filedialog.askdirectory(parent=win,title="Choose extraction folder")
            if not dest:return
            if not messagebox.askyesno("Confirm extraction",f"Extract archive into:\n{dest}\n\nOnly continue if you trust this archive.",parent=win):return
            try:
                root=Path(dest).resolve()
                with zipfile.ZipFile(source) as z:
                    members=[]
                    for info in z.infolist():
                        p=Path(info.filename)
                        if p.is_absolute() or ".." in p.parts:raise ValueError("Archive contains an unsafe path; nothing was extracted.")
                        target=(root/p).resolve()
                        if target!=root and root not in target.parents:raise ValueError("Archive path escapes destination.")
                        members.append(info)
                    z.extractall(root,members=members)
                status.config(text=f"Extracted {len(members)} entries to {root}")
            except Exception as e:messagebox.showerror("Archive Manager",str(e),parent=win)
        row=tk.Frame(win,bg="#f3f6fb"); row.pack(anchor="w",padx=20)
        for label,fn in [("Create ZIP",create_zip),("Inspect ZIP",inspect),("Extract ZIP",extract)]:tk.Button(row,text=label,command=fn,bg=self.accent if label=="Create ZIP" else "#dbeafe",fg="white" if label=="Create ZIP" else "#172238",relief="flat",padx=12,pady=8).pack(side="left",padx=5)

    def scientific_calculator_22(self):
        """Calculator restricted to safe arithmetic and selected math functions."""
        win=self.window("NevOS 22.0 — Scientific Calculator", "520x440"); win.configure(bg="#f3f6fb")
        tk.Label(win,text="Scientific Calculator",font=("Segoe UI",20,"bold"),bg="#f3f6fb",fg="#172238").pack(anchor="w",padx=18,pady=(16,8))
        expr=tk.StringVar(); entry=tk.Entry(win,textvariable=expr,font=("Consolas",17),justify="right",relief="flat"); entry.pack(fill="x",padx=18,pady=8,ipady=9); entry.focus_set()
        out=tk.Label(win,text="Ready",bg="#f3f6fb",fg="#64748b"); out.pack(anchor="w",padx=20)
        grid=tk.Frame(win,bg="#f3f6fb"); grid.pack(fill="both",expand=True,padx=14,pady=12)
        buttons=[("sin(","sin("),("cos(","cos("),("tan(","tan("),("sqrt(","sqrt("),("π","pi"),("log(","log("),("7","7"),("8","8"),("9","9"),("÷","/"),("4","4"),("5","5"),("6","6"),("×","*"),("1","1"),("2","2"),("3","3"),("−","-"),("0","0"),(".","."),("(","("),( ")",")"),("+","+"),("Clear","CLEAR"),("=","EQUAL")]
        for i,(label,val) in enumerate(buttons):
            def press(v=val):
                if v=="CLEAR":expr.set("");out.config(text="Ready")
                elif v=="EQUAL":
                    try:
                        tree=ast.parse(expr.get().replace("π","pi"),mode="eval"); allowed=(ast.Expression,ast.BinOp,ast.UnaryOp,ast.Constant,ast.Call,ast.Name,ast.Load,ast.Add,ast.Sub,ast.Mult,ast.Div,ast.FloorDiv,ast.Mod,ast.Pow,ast.USub,ast.UAdd)
                        if any(not isinstance(n,allowed) for n in ast.walk(tree)):raise ValueError("Unsupported expression")
                        funcs={"sin":math.sin,"cos":math.cos,"tan":math.tan,"sqrt":math.sqrt,"log":math.log,"pi":math.pi,"e":math.e,"abs":abs}
                        for n in ast.walk(tree):
                            if isinstance(n,ast.Name) and n.id not in funcs:raise ValueError("Unknown function or name")
                            if isinstance(n,ast.Call) and (not isinstance(n.func,ast.Name) or n.func.id not in funcs or n.func.id in ("pi","e")):raise ValueError("Unsupported function")
                        result=eval(compile(tree,"<calculator>","eval"),{"__builtins__":{}},funcs)
                        if not isinstance(result,(int,float)) or not math.isfinite(result) or abs(result)>1e100:raise ValueError("Result out of range")
                        expr.set(str(result));out.config(text="Calculated successfully")
                    except Exception as e:out.config(text=f"Cannot calculate: {e}")
                else:expr.set(expr.get()+v)
            tk.Button(grid,text=label,command=press,bg="white",fg="#172238",relief="flat",font=("Segoe UI",10),padx=5,pady=7).grid(row=i//5,column=i%5,sticky="nsew",padx=3,pady=3)
        for i in range(5):grid.columnconfigure(i,weight=1)
        for i in range(5):grid.rowconfigure(i,weight=1)
        entry.bind("<Return>",lambda e: next((w for w in grid.winfo_children() if w.cget("text")=="="),None).invoke())

