    def nevos_arcade_23(self):
        """Xbox-inspired local arcade with eight small games; no Xbox branding or online account required."""
        import random, time
        win = tk.Toplevel(self.root)
        win.title("NevOS Arcade · 23.0")
        win.geometry("900x650")
        win.minsize(720, 520)
        bg, panel, fg, muted = "#0b1020", "#151d32", "#f8fafc", "#a8b6cf"
        win.configure(bg=bg)
        header=tk.Frame(win,bg=bg); header.pack(fill="x",padx=22,pady=(18,10))
        tk.Label(header,text="NEVOS ARCADE",font=("Segoe UI",24,"bold"),bg=bg,fg="#8bffb7").pack(anchor="w")
        tk.Label(header,text="A game lounge inspired by console dashboards · 8 games · local play",font=("Segoe UI",10),bg=bg,fg=muted).pack(anchor="w",pady=(2,0))
        tabs=ttk.Notebook(win); tabs.pack(fill="both",expand=True,padx=18,pady=(0,18))
        def page(name):
            f=tk.Frame(tabs,bg=panel); tabs.add(f,text=name); return f
        def label(f,text,size=13,color=fg): tk.Label(f,text=text,font=("Segoe UI",size,"bold" if size>=16 else "normal"),bg=panel,fg=color).pack(pady=8)
        def buttonrow(f,items):
            r=tk.Frame(f,bg=panel);r.pack(pady=8)
            for text,cmd in items: tk.Button(r,text=text,command=cmd,bg="#263653",fg=fg,activebackground="#365477",activeforeground=fg,relief="flat",padx=13,pady=8,cursor="hand2").pack(side="left",padx=4)
        # 1 Number Quest
        f=page("Number Quest"); secret=[random.randint(1,100)]; tries=[0]
        label(f,"NUMBER QUEST",20,"#8bffb7"); label(f,"Guess the hidden number from 1 to 100")
        e=tk.Entry(f,font=("Segoe UI",16),justify="center",width=12);e.pack(pady=6)
        out=tk.Label(f,text="Ready when you are!",font=("Segoe UI",12),bg=panel,fg=muted);out.pack(pady=8)
        def guess():
            try:n=int(e.get()); assert 1<=n<=100
            except Exception:out.config(text="Enter a whole number between 1 and 100.");return
            tries[0]+=1;out.config(text=(f"🎉 You got it in {tries[0]} guesses!" if n==secret[0] else "Too low — try again!" if n<secret[0] else "Too high — try again!"))
        def newguess():secret[0]=random.randint(1,100);tries[0]=0;e.delete(0,'end');out.config(text="New number selected!")
        buttonrow(f,[("Guess",guess),("New game",newguess)])
        # 2 RPS
        f=page("Duel"); label(f,"ROCK · PAPER · SCISSORS",18,"#8bffb7"); rr=tk.Label(f,text="Choose your move to start a duel.",font=("Segoe UI",12),bg=panel,fg=muted);rr.pack(pady=22); wins=[0,0,0]
        def duel(m):
            c=random.choice(["Rock","Paper","Scissors"]); result="Draw" if m==c else "You win!" if (m,c) in [("Rock","Scissors"),("Paper","Rock"),("Scissors","Paper")] else "CPU wins";wins[0]+=result=="You win!";wins[1]+=result=="CPU wins";rr.config(text=f"You: {m}    CPU: {c}\n{result}\nWins {wins[0]} · Losses {wins[1]} · Draws {wins[2]}")
            if result=="Draw":wins[2]+=1
        buttonrow(f,[(m,lambda x=m:duel(x)) for m in ["Rock","Paper","Scissors"]])
        # 3 Reaction clicker (safe button-click timer)
        f=page("Reaction"); label(f,"REACTION RUSH",20,"#8bffb7"); info=tk.Label(f,text="Press Start, then click the target as many times as possible in 10 seconds.",bg=panel,fg=muted,wraplength=600);info.pack(pady=10); score=[0]; active=[False]; end=[0.0]
        scorelab=tk.Label(f,text="Score: 0",font=("Segoe UI",20,"bold"),bg=panel,fg=fg);scorelab.pack(pady=10)
        target=tk.Button(f,text="START",font=("Segoe UI",18,"bold"),bg="#107c41",fg="white",relief="flat",padx=30,pady=20);target.pack(pady=12)
        def tick():
            if active[0] and time.monotonic()>=end[0]:active[0]=False;target.config(text="TIME!",state="disabled");info.config(text=f"Time's up! Final score: {score[0]}. Press Start to play again.");return
            if active[0]:win.after(100,tick)
        def hit():
            if not active[0]:score[0]=0;active[0]=True;end[0]=time.monotonic()+10;target.config(text="CLICK!",state="normal");info.config(text="Go go go! 10 seconds!");scorelab.config(text="Score: 0");tick()
            else:score[0]+=1;scorelab.config(text=f"Score: {score[0]}")
        target.config(command=hit)
        # 4 Memory match
        f=page("Memory"); label(f,"MEMORY MATCH",18,"#8bffb7"); symbols=["🍀","🚀","🎮","⭐","🍀","🚀","🎮","⭐"];random.shuffle(symbols); shown=[];matched=set(); moves=[0]
        status=tk.Label(f,text="Find all four matching pairs.",bg=panel,fg=muted);status.pack(pady=8);grid=tk.Frame(f,bg=panel);grid.pack(pady=8); cards=[]
        def flip(i):
            if i in matched or any(j==i for j,_ in shown) or len(shown)>=2:return
            cards[i].config(text=symbols[i]);shown.append((i,symbols[i]))
            if len(shown)==2:
                moves[0]+=1
                if shown[0][1]==shown[1][1]:matched.update([shown[0][0],shown[1][0]]);status.config(text=f"Pair found! Moves: {moves[0]}");shown.clear()
                else:
                    a,b=shown;shown.clear()
                    def hide():
                        if a[0] not in matched:cards[a[0]].config(text="?")
                        if b[0] not in matched:cards[b[0]].config(text="?")
                    win.after(650,hide);status.config(text=f"No match. Moves: {moves[0]}")
                if len(matched)==8:status.config(text=f"🏆 All pairs found in {moves[0]} moves!")
        for i in range(8):
            b=tk.Button(grid,text="?",font=("Segoe UI Emoji",18),width=5,height=2,bg="#263653",fg=fg,relief="flat",command=lambda j=i:flip(j));b.grid(row=i//4,column=i%4,padx=5,pady=5);cards.append(b)
        # 5 Tic tac toe
        f=page("Tic-Tac-Toe");label(f,"TIC-TAC-TOE",18,"#8bffb7"); board=[""]*9; status=tk.Label(f,text="Your turn: X",bg=panel,fg=muted);status.pack(pady=5);g=tk.Frame(f,bg=panel);g.pack()
        def resetttt():
            board[:]=[""]*9
            for b in cells:b.config(text="",state="normal")
            status.config(text="Your turn: X")
        def move(i):
            if board[i] or checkwinner(board):return
            board[i]="X";cells[i].config(text="X")
            if checkwinner(board):status.config(text="You win!");return
            if all(board):status.config(text="Draw!");return
            choices=[j for j,x in enumerate(board) if not x];j=random.choice(choices);board[j]="O";cells[j].config(text="O")
            status.config(text="CPU wins!" if checkwinner(board) else "Draw!" if all(board) else "Your turn: X")
        def checkwinner(b):return any(b[a] and b[a]==b[c]==b[d] for a,c,d in [(0,1,2),(3,4,5),(6,7,8),(0,3,6),(1,4,7),(2,5,8),(0,4,8),(2,4,6)])
        cells=[]
        for i in range(9):b=tk.Button(g,text="",font=("Segoe UI",20,"bold"),width=4,height=1,bg="#263653",fg=fg,relief="flat",command=lambda j=i:move(j));b.grid(row=i//3,column=i%3,padx=3,pady=3);cells.append(b)
        buttonrow(f,[("Restart",resetttt)])
        # 6 Quick math
        f=page("Math Sprint");label(f,"MATH SPRINT",18,"#8bffb7");problem=tk.Label(f,text="Press New Problem",font=("Segoe UI",17),bg=panel,fg=fg);problem.pack(pady=14);ans=tk.Entry(f,font=("Segoe UI",15),justify="center",width=10);ans.pack();mout=tk.Label(f,text="Score: 0",bg=panel,fg=muted);mout.pack(pady=8);mathstate=[0,0]
        def mathnew():
            a,b=random.randint(2,20),random.randint(2,12);op=random.choice(["+","−","×"]);mathstate[:]=[a+b if op=="+" else a-b if op=="−" else a*b,mathstate[1]];problem.config(text=f"{a} {op} {b} = ?");ans.delete(0,"end")
        def mathcheck():
            try:ok=int(ans.get())==mathstate[0]
            except ValueError:ok=False
            mathstate[1]+=1 if ok else 0;mout.config(text=("Correct! " if ok else "Not quite. ")+f"Score: {mathstate[1]}");mathnew()
        buttonrow(f,[("New problem",mathnew),("Check answer",mathcheck)])
        # 7 Pong-lite
        f=page("Pong Lite");label(f,"PONG LITE",18,"#8bffb7");label(f,"Move your paddle with the buttons. First to 5 wins.",10,muted);state=[0,0,0];pl=tk.Label(f,text="You 0  —  CPU 0",font=("Segoe UI",18),bg=panel,fg=fg);pl.pack(pady=15);msg=tk.Label(f,text="Ready?",bg=panel,fg=muted);msg.pack()
        def pong():
            state[2]+=1;state[1]+=random.choice([0,0,1]);pl.config(text=f"You {state[0]}  —  CPU {state[1]}");msg.config(text="You win the rally!" if state[2]%2 else "CPU returned the ball!")
            if state[0]>=5 or state[1]>=5:msg.config(text="You win the match!" if state[0]>state[1] else "CPU wins the match!");state[:]=[0,0,0]
        buttonrow(f,[("Hit left",lambda:(state.__setitem__(0,state[0]+1),pong())) ,("Play rally",pong)])
        # 8 Guess-the-word
        f=page("Word Scramble");label(f,"WORD SCRAMBLE",18,"#8bffb7");words=["PLANET","PYTHON","GAMING","ROCKET","PUZZLE","WINDOWS"];word=[random.choice(words)];scramble=tk.Label(f,text="",font=("Segoe UI",22,"bold"),bg=panel,fg=fg);scramble.pack(pady=15);wordentry=tk.Entry(f,font=("Segoe UI",14),justify="center");wordentry.pack();wout=tk.Label(f,text="Unscramble the letters!",bg=panel,fg=muted);wout.pack(pady=8)
        def newword():word[0]=random.choice(words);scramble.config(text="  ".join(random.sample(list(word[0]),len(word[0]))));wordentry.delete(0,"end");wout.config(text="Unscramble the letters!")
        def checkword():wout.config(text="Correct! 🎉" if wordentry.get().strip().upper()==word[0] else "Try again!")
        buttonrow(f,[("Check",checkword),("New word",newword)]);newword()
        tk.Label(win,text="Games run locally inside NevOS. Scores are session-only; this is not an Xbox service.",bg=bg,fg=muted,font=("Segoe UI",9)).pack(pady=(0,8))


    def gamer_profile_24(self):
        import json
        from pathlib import Path
        win=tk.Toplevel(self.root); win.title("NevOS Gamer Profile & Achievements"); win.geometry("650x520"); win.configure(bg="#0b1020")
        bg="#0b1020"; fg="#f8fafc"; muted="#a8b6cf"; green="#8bffb7"
        tk.Label(win,text="GAMER PROFILE",font=("Segoe UI",24,"bold"),bg=bg,fg=green).pack(anchor="w",padx=22,pady=(20,4))
        tk.Label(win,text="Local profile, XP and achievements",bg=bg,fg=muted).pack(anchor="w",padx=22)
        data_path=Path.home()/".nevos7"/"gamer_profile_24.json"
        try: data=json.loads(data_path.read_text(encoding="utf-8"))
        except Exception: data={"name":"Player One","xp":0,"achievements":[]}
        body=tk.Frame(win,bg=bg); body.pack(fill="both",expand=True,padx=22,pady=18)
        tk.Label(body,text="Player name",bg=bg,fg=fg).pack(anchor="w")
        name=tk.Entry(body,font=("Segoe UI",12)); name.insert(0,str(data.get("name","Player One"))); name.pack(fill="x",pady=6)
        xp=int(data.get("xp",0)); level=xp//100+1
        stat=tk.Label(body,text=f"Level {level}  •  {xp} XP",font=("Segoe UI",18,"bold"),bg=bg,fg=green); stat.pack(anchor="w",pady=10)
        tk.Label(body,text="Achievements",font=("Segoe UI",14,"bold"),bg=bg,fg=fg).pack(anchor="w",pady=(8,4))
        ach=tk.Listbox(body,height=8,font=("Segoe UI",11),bg="#151d32",fg=fg,selectbackground="#107c41",relief="flat")
        items=["🎮 Arcade Explorer — opened the arcade","🏆 Profile Creator — saved a gamer profile","⭐ XP Starter — earned your first XP"]
        for item in items: ach.insert("end",("✓ " if item.split(" — ")[0] in data.get("achievements",[]) else "🔒 ")+item)
        ach.pack(fill="both",expand=True)
        def save():
            data["name"]=name.get().strip() or "Player One"; data["xp"]=max(xp,50); data["achievements"]=["🏆 Profile Creator"]
            try:
                data_path.parent.mkdir(parents=True,exist_ok=True); data_path.write_text(json.dumps(data,indent=2),encoding="utf-8")
                stat.config(text=f"Level {data['xp']//100+1}  •  {data['xp']} XP")
                ach.delete(0,"end")
                for item in items: ach.insert("end",("✓ " if item.split(" — ")[0] in data["achievements"] else "🔒 ")+item)
                messagebox.showinfo("Gamer Profile","Profile saved locally.",parent=win)
            except Exception as e: messagebox.showerror("Save failed",str(e),parent=win)
        tk.Button(body,text="Save profile + earn 50 XP",command=save,bg="#107c41",fg="white",relief="flat",padx=12,pady=8).pack(anchor="w",pady=10)

