    def _cc2_settings_file(self):
        path = self._data_dir() / "control_center_settings.json"
        path.parent.mkdir(parents=True, exist_ok=True)
        return path

    def _cc2_load_settings(self):
        try:
            with open(self._cc2_settings_file(), "r", encoding="utf-8") as f:
                data = json.load(f)
            return data if isinstance(data, dict) else {}
        except (OSError, ValueError, TypeError):
            return {}

    def _cc2_save_settings(self):
        data = {
            "wallpaper": getattr(self, "wallpaper", BG_DEFAULT),
            "accent": getattr(self, "accent", ACCENT_DEFAULT),
            "saved_at": datetime.now().isoformat(timespec="seconds"),
        }
        try:
            with open(self._cc2_settings_file(), "w", encoding="utf-8") as f:
                json.dump(data, f, indent=2)
        except OSError:
            pass

